-- ============================================================
-- 0039 — Curadoria dos textos-base da RNC: Segurança do Trabalho (ST)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- ST-01 (12 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a atividade em execução envolver risco grave e iminente (altura, energia, espaço confinado) sem a APR presente na frente de serviço',
  texto_fundamentacao_normativa = 'A Análise Preliminar de Risco (APR) é o instrumento de campo que materializa o gerenciamento de riscos ocupacionais e deve permanecer acessível, impressa ou em meio digital, no exato local da atividade. Aplica-se a NR-01, que institui o Gerenciamento de Riscos Ocupacionais (GRO) e exige a identificação de perigos e a avaliação de riscos por atividade. O critério ''APR impressa/digital acessível no local da atividade'' integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois sem o documento disponível a equipe não dispõe da referência dos controles definidos.',
  texto_risco_consequencia = 'A ausência da APR na frente de serviço priva os executantes da referência dos perigos e das medidas de controle da tarefa, favorecendo a adoção de métodos improvisados e a exposição a riscos não avaliados, com potencial de acidente. Enquanto a condição persistir, a atividade transcorre sem respaldo documental do controle de riscos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) providenciar imediatamente a APR correspondente à atividade e mantê-la afixada ou disponível em meio digital na frente de serviço; (ii) confirmar com a equipe a leitura e o entendimento dos riscos e controles ali descritos antes de retomar a tarefa; (iii) evidenciar a correção com registro fotográfico do documento no local ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver executantes atuando na tarefa sem qualquer assinatura, caracterizando ausência de ciência formal dos riscos',
  texto_fundamentacao_normativa = 'A assinatura de todos os executantes e do responsável na APR comprova a ciência formal dos riscos e o comprometimento com os controles, elemento essencial da gestão de riscos preconizada pela NR-01. O critério ''Assinaturas de toda a equipe e do responsável'' integra o plano de inspeção e é requisito verificável: a APR sem a adesão documentada de quem executa não cumpre sua função de comunicação e responsabilização, ficando prejudicada a rastreabilidade da ordem de serviço.',
  texto_risco_consequencia = 'A APR sem as assinaturas de toda a equipe não evidencia que cada trabalhador tomou ciência dos perigos e controles, fragilizando a rastreabilidade da comunicação de riscos e podendo permitir que executantes atuem desinformados sobre as medidas previstas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reunir a equipe e o responsável para leitura da APR e coleta das assinaturas faltantes antes do prosseguimento; (ii) verificar se todos os presentes na atividade constam na relação de executantes; (iii) evidenciar a correção com registro fotográfico da APR assinada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a atividade real apresentar riscos relevantes não previstos na APR (ex.: alteração para trabalho em altura ou a quente)',
  texto_fundamentacao_normativa = 'A APR deve refletir fielmente as etapas e os riscos da atividade efetivamente executada; divergências entre o descrito e o realizado invalidam a análise e os controles dela derivados. A NR-01 exige que a avaliação de riscos seja aderente à atividade real como base do GRO. O critério ''Riscos e etapas descritos correspondem ao que está sendo executado'' é requisito verificável de aceitação da tarefa: uma APR genérica, de outra frente ou desatualizada não protege o trabalho em curso.',
  texto_risco_consequencia = 'APR incompatível com a atividade real deixa perigos efetivos sem controle definido e induz a equipe a seguir procedimentos que não correspondem ao trabalho executado, elevando a probabilidade de acidente por risco não avaliado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a atividade e revisar a APR para descrever as etapas e os riscos realmente presentes; (ii) definir e comunicar à equipe os controles correspondentes às condições atuais da frente de serviço; (iii) evidenciar a correção com registro fotográfico da APR revisada e da atividade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em caso de reincidência ou quando a atividade do dia envolver riscos especiais sem o Diálogo Diário de Segurança registrado',
  texto_fundamentacao_normativa = 'O Diálogo Diário de Segurança (DDS) é prática consagrada de comunicação e conscientização de riscos no início da jornada, alinhada ao dever de informação e capacitação previsto na NR-01, ainda que sua forma específica decorra do procedimento de SSMA da obra. O critério ''Registro diário com tema, lista de presença e assinaturas'' integra o plano de inspeção como evidência verificável de que a orientação foi efetivamente realizada e recebida pela equipe.',
  texto_risco_consequencia = 'A falta de realização ou de registro do DDS reduz a assimilação diária dos riscos e controles pela equipe e elimina a evidência de que a orientação de segurança ocorreu, enfraquecendo a cultura preventiva e a rastreabilidade exigida na obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar o DDS do dia abordando os riscos da atividade e registrar tema, data e lista de presença assinada; (ii) padronizar o formulário de DDS e a rotina de arquivamento diário; (iii) evidenciar a correção com registro fotográfico do DDS e da lista de presença ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — atividade especial (altura, quente, elétrica ou confinado) sem Permissão de Trabalho válida caracteriza risco grave e iminente e enseja paralisação imediata',
  texto_fundamentacao_normativa = 'A Permissão de Trabalho (PT) é o documento que autoriza e condiciona a execução de atividades de alto risco, exigindo a checagem prévia das medidas de controle antes da liberação. Para espaço confinado a NR-33 exige a Permissão de Entrada e Trabalho; para trabalho em altura a NR-35 exige análise de risco e autorização/permissão de trabalho; para serviços em instalações elétricas a NR-10 impõe autorização e controle das intervenções. O critério ''PT válida para atividades especiais (altura, quente, elétrica, confinado)'' é requisito verificável e condição de liberação da tarefa.',
  texto_risco_consequencia = 'Executar atividade especial sem PT válida significa liberar trabalho de alto risco sem a verificação formal dos controles críticos, expondo a equipe a queda, incêndio ou explosão, choque elétrico ou atmosfera perigosa, com potencial de acidente grave ou fatal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar imediatamente a atividade especial até a emissão da PT pelo emitente autorizado; (ii) verificar em campo o atendimento a todas as medidas de controle e condicionantes da PT antes da liberação; (iii) evidenciar a correção com registro fotográfico da PT emitida e das condições checadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de treinamento válido recair sobre atividade de alto risco regulada por NR específica (ex.: NR-35, NR-33, NR-10)',
  texto_fundamentacao_normativa = 'A capacitação dos trabalhadores para a atividade é requisito do GRO: cabe à NR-01 estabelecer o dever geral de treinamento e às normas específicas definir conteúdo, carga horária e validade dos certificados conforme o risco — por exemplo, NR-35 para trabalho em altura, NR-33 para espaço confinado e NR-10 para instalações elétricas. O critério ''Certificados válidos das NRs aplicáveis'' é requisito verificável de aceitação, pois a habilitação documentada precede a autorização para executar a tarefa.',
  texto_risco_consequencia = 'Equipe sem treinamento válido para a atividade não domina os procedimentos seguros nem o uso correto dos controles, elevando a probabilidade de erro de execução e de acidente, além de expor a obra a autuação por descumprimento das exigências de capacitação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar da atividade o trabalhador sem certificação válida até a regularização; (ii) providenciar ou atualizar os treinamentos das NRs aplicáveis e arquivar os certificados na obra; (iii) evidenciar a correção com registro fotográfico ou cópia dos certificados válidos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a atividade exigir autorização específica por NR (ex.: NR-10 para eletricidade, NR-35 para altura) e o executante não a possuir',
  texto_fundamentacao_normativa = 'A autorização formal é o ato documentado que habilita nominalmente o trabalhador a executar atividades reguladas, distinto do treinamento: a NR-10 exige que o profissional seja qualificado, habilitado, capacitado e autorizado para intervenções em instalações elétricas, e a NR-35 exige autorização para trabalho em altura mediante aptidão e treinamento. O critério ''Autorização documentada (ex.: NR-10, NR-35)'' é requisito verificável e pressuposto para a liberação do executante na tarefa.',
  texto_risco_consequencia = 'Trabalhador não autorizado formalmente pode executar atividade regulada sem que a empresa tenha verificado e registrado sua aptidão, rompendo a cadeia de responsabilização e ampliando o risco de acidente em serviço que exige habilitação específica. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) impedir a atuação do trabalhador não autorizado na atividade regulada até a emissão da autorização; (ii) formalizar a autorização com base na aptidão e no treinamento válidos, mantendo o documento na obra; (iii) evidenciar a correção com registro fotográfico ou cópia da autorização formal ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se ferramenta ou equipamento reprovado permanecer em uso, especialmente em atividade de alto risco',
  texto_fundamentacao_normativa = 'A inspeção pré-uso de ferramentas e equipamentos, com preenchimento de checklist e segregação dos itens reprovados, é medida de controle que assegura condições seguras de operação e integra o gerenciamento de riscos da NR-01; para máquinas e equipamentos aplicam-se ainda os requisitos de manutenção e segurança da NR-12. O critério ''Checklist pré-uso preenchido, itens reprovados segregados'' é requisito verificável de aceitação, evitando que dispositivos defeituosos cheguem à frente de serviço.',
  texto_risco_consequencia = 'Ferramentas e equipamentos não inspecionados, ou reprovados que permaneçam em uso, podem falhar durante a operação, provocando choque, projeção de partículas, ruptura, prensamento ou queda, com risco de lesão ao operador e a terceiros. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) aplicar o checklist pré-uso a todas as ferramentas e equipamentos da frente de serviço; (ii) segregar e identificar os itens reprovados, retirando-os de uso até reparo ou descarte; (iii) evidenciar a correção com registro fotográfico dos checklists preenchidos e da segregação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a atividade envolver riscos relevantes e os trabalhadores não souberem descrever os controles aplicáveis',
  texto_fundamentacao_normativa = 'A efetiva comunicação dos riscos e controles à equipe é dever de informação inerente ao GRO da NR-01 e condição para que as medidas de proteção sejam de fato observadas em campo. O critério ''Trabalhadores sabem descrever os riscos e controles da tarefa'' é requisito verificável por entrevista de campo: não basta o documento existir, é preciso que a informação tenha sido compreendida por quem executa a atividade.',
  texto_risco_consequencia = 'Quando os trabalhadores não sabem descrever os riscos e controles da tarefa, evidencia-se falha na comunicação de segurança, o que aumenta a chance de exposição a perigos por desconhecimento e de não utilização correta das medidas de controle previstas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reforçar a comunicação dos riscos e controles da atividade junto à equipe, confirmando o entendimento por meio de perguntas dirigidas; (ii) registrar a orientação complementar na APR ou no DDS; (iii) evidenciar a correção com registro fotográfico da orientação e do registro assinado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando ausente controle para risco grave e iminente ou quando se recorrer apenas a EPI havendo medida coletiva viável não implantada',
  texto_fundamentacao_normativa = 'As medidas de controle devem ser implantadas segundo a hierarquia — eliminação, substituição, controles de engenharia, controles administrativos e, por fim, EPI —, ordem expressamente adotada pelo GRO da NR-01 para o tratamento dos riscos ocupacionais. O critério ''Hierarquia de controles aplicada (eliminação → EPI)'' é requisito verificável de aceitação: priorizar EPI sem esgotar as medidas superiores caracteriza controle inadequado do risco.',
  texto_risco_consequencia = 'A não implantação das medidas de controle previstas, ou a inversão da hierarquia recorrendo diretamente ao EPI, mantém o risco insuficientemente tratado na fonte e transfere ao trabalhador a última barreira de proteção, elevando a gravidade das consequências em caso de falha. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar as medidas de controle na ordem hierárquica, priorizando eliminação, engenharia e controles administrativos antes do EPI; (ii) verificar em campo a efetividade dos controles adotados para a atividade; (iii) evidenciar a correção com registro fotográfico dos controles implantados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a mudança de escopo introduzir risco especial (altura, quente, elétrica, confinado) sem revisão da APR/PT correspondente',
  texto_fundamentacao_normativa = 'Toda alteração de método, escopo ou condição de uma atividade deve disparar a reavaliação dos riscos e a revisão da APR e, quando aplicável, da PT, sob pena de a análise vigente não mais corresponder à execução — exigência coerente com a gestão de mudanças e a atualização contínua do GRO na NR-01. O critério ''Alteração de escopo gerou revisão da APR/PT'' é requisito verificável de aceitação da continuidade segura da tarefa.',
  texto_risco_consequencia = 'Mudanças na atividade não reavaliadas fazem com que a APR/PT em uso deixe de refletir os riscos reais, permitindo que novos perigos introduzidos pela alteração permaneçam sem controle definido, com aumento da probabilidade de acidente. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a atividade alterada até a reavaliação dos riscos decorrentes da mudança; (ii) revisar a APR e, se aplicável, reemitir a PT contemplando as novas condições e controles; (iii) evidenciar a correção com registro fotográfico da APR/PT revisada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 11;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o PGR estiver ausente, vencido ou sem plano de ação para riscos relevantes já identificados no canteiro',
  texto_fundamentacao_normativa = 'O Programa de Gerenciamento de Riscos (PGR) é o documento base do GRO, contendo o inventário de riscos e o plano de ação, cuja elaboração e manutenção atualizada são exigidas pela NR-01; na indústria da construção, a NR-18 reforça a gestão de segurança e saúde no canteiro. O critério ''Inventário de riscos e plano de ação vigentes'' é requisito verificável de aceitação: um PGR desatualizado não orienta o tratamento dos riscos reais da obra.',
  texto_risco_consequencia = 'PGR desatualizado ou sem plano de ação vigente descaracteriza o gerenciamento de riscos do canteiro, deixando perigos identificados sem tratamento planejado e sem responsáveis e prazos definidos, o que compromete toda a cadeia de controle e a conformidade legal da obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) atualizar o PGR com o inventário de riscos vigente e o respectivo plano de ação, contemplando responsáveis e prazos; (ii) integrar ao PGR as medidas de controle e os riscos identificados nas frentes de serviço; (iii) evidenciar a correção com registro fotográfico ou cópia do PGR atualizado e assinado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-01' and item_numero = 12;

-- ST-02 (14 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver risco de queda de objetos, energização ou trabalho em altura/içamento com o capacete sem jugular ou mal ajustado.',
  texto_fundamentacao_normativa = 'A proteção do crânio por capacete de segurança com jugular ajustada é EPI obrigatório em frentes com risco de impacto, queda de objetos e projeção, condição verificável em campo. Aplicam-se a NR-06 (Equipamento de Proteção Individual), que impõe o fornecimento, o uso e a adequação do EPI ao risco, e a NR-18 (segurança e saúde no trabalho na indústria da construção), que exige a proteção da cabeça nas frentes de obra. O critério "uso correto, jugular ajustada em altura/içamento" integra o plano de inspeção e constitui requisito de aceitação da frente, pois a jugular impede a perda do capacete durante a movimentação vertical.',
  texto_risco_consequencia = 'Capacete sem jugular ou mal ajustado pode se desprender em içamento ou queda, deixando o crânio exposto a impacto e queda de objetos, com potencial de lesão craniana grave ou fatal ao trabalhador. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a exposição do trabalhador na frente até a regularização; (ii) substituir ou reajustar o capacete e a jugular, conferindo a validade do CA e o correto travamento; (iii) reforçar a orientação de uso em DDS e evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em atividades com projeção de partículas, respingo químico, solda ou radiação UV realizadas sem a proteção ocular compatível.',
  texto_fundamentacao_normativa = 'A proteção ocular por óculos compatível com o risco (impacto, radiação UV, respingo químico) é EPI obrigatório sempre que a atividade expuser os olhos e a face a agentes agressivos. Aplica-se a NR-06, que condiciona a seleção do EPI à natureza do risco e determina o fornecimento de proteção adequada. O critério "compatível com o risco (impacto, UV, respingo)" integra o plano de inspeção: um óculos genérico não substitui a proteção específica contra radiação de solda ou contra respingo no manuseio de produtos químicos, de modo que a compatibilidade, e não a mera presença, é o requisito de aceitação.',
  texto_risco_consequencia = 'Proteção ocular ausente ou incompatível com o agente expõe o trabalhador a lesões de córnea, queimadura química ou térmica e perda parcial ou total da visão, dano frequentemente irreversível. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a atividade de risco ocular até o fornecimento do EPI correto; (ii) selecionar e entregar o óculos compatível com o agente específico (impacto, UV/solda ou respingo químico), com CA vigente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica onde houver risco de perfuração, esmagamento por carga ou circulação de equipamentos pesados com o calçado danificado.',
  texto_fundamentacao_normativa = 'O calçado de segurança com biqueira adequada e solado íntegro é EPI obrigatório de proteção dos membros inferiores nas frentes de obra. Aplicam-se a NR-06, quanto ao fornecimento e à adequação do EPI, e a NR-18, quanto às condições de segurança na construção. O critério "biqueira adequada, solado íntegro" integra o plano de inspeção: solado gasto ou descolado compromete a aderência e a proteção contra perfuração, e a biqueira inadequada não resiste ao esmagamento previsto para a frente.',
  texto_risco_consequencia = 'Botina danificada ou inadequada expõe o pé a esmagamento por queda de carga, perfuração por prego ou vergalhão e escorregamento, com risco de fratura, laceração e afastamento do trabalhador. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar o trabalhador da frente enquanto persistir o calçado danificado; (ii) substituir a botina por unidade íntegra, com biqueira compatível, solado em condições de uso e CA vigente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em frentes com risco elétrico ou de inflamáveis onde for exigida vestimenta antichama e esta estiver ausente.',
  texto_fundamentacao_normativa = 'A vestimenta de trabalho íntegra, de manga longa, e antichama onde exigido, protege a pele contra abrasão, respingo, radiação e chama. Aplica-se a NR-06 quanto ao fornecimento de vestimentas de proteção; a exigência de característica antichama vincula-se ao risco específico da frente (por exemplo, risco elétrico sob a NR-10 ou atividades com inflamáveis), conforme a análise de risco e, quando o requisito derivar do projeto, o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "manga longa, uniforme íntegro; antichama onde exigido" integra o plano de inspeção como requisito verificável de aceitação.',
  texto_risco_consequencia = 'Vestimenta rasgada, de manga curta ou sem propriedade antichama onde exigida expõe o trabalhador a queimaduras por arco elétrico, respingo de solda ou contato com inflamáveis, além de abrasões, agravando a extensão de eventuais lesões. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) adequar imediatamente a vestimenta ao risco da frente, substituindo peças danificadas; (ii) fornecer vestimenta antichama com CA vigente onde a análise de risco assim exigir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e registrar a entrega na ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em serviços com risco elétrico (luva isolante) ou químico, onde a luva incorreta não oferece proteção alguma ao agente.',
  texto_fundamentacao_normativa = 'A luva de proteção deve ser do tipo compatível com o agente da tarefa — mecânica, isolante, química ou anticorte — pois cada classe protege contra um risco distinto. Aplica-se a NR-06, que vincula a seleção do EPI à natureza do risco; em serviços elétricos, a exigência de luva isolante decorre da NR-10. O critério "tipo compatível: mecânica, isolante, química, corte" integra o plano de inspeção: uma luva mecânica não isola eletricamente nem barra agente químico, de modo que o tipo, e não a simples presença de luva, é o requisito de aceitação.',
  texto_risco_consequencia = 'Luva incompatível com o agente da tarefa oferece falsa sensação de proteção e expõe as mãos a corte, choque elétrico, queimadura química ou lesão mecânica, com risco de amputação ou intoxicação. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a tarefa até a disponibilização da luva correta; (ii) selecionar e entregar a luva do tipo compatível com o agente (mecânica, isolante, química ou anticorte), com CA vigente e, no caso de isolante, ensaio e validade em dia; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em exposição contínua a ruído elevado sem proteção, dado o caráter cumulativo e irreversível da perda auditiva.',
  texto_fundamentacao_normativa = 'O protetor auditivo é obrigatório em áreas cuja exposição ao ruído atinja ou ultrapasse o limite de tolerância. Aplicam-se a NR-06, quanto ao fornecimento do EPI, e a NR-15 (atividades e operações insalubres), cujo Anexo 1 estabelece os limites de tolerância para ruído contínuo ou intermitente, sendo 85 dB(A) o limite para a jornada de 8 horas. O critério "uso em áreas com ruído ≥ 85 dB(A)" integra o plano de inspeção e decorre da avaliação de risco (PGR), constituindo requisito verificável de aceitação da área.',
  texto_risco_consequencia = 'A exposição a ruído igual ou superior a 85 dB(A) sem protetor auditivo provoca perda auditiva induzida por ruído, dano cumulativo e irreversível, além de zumbido e fadiga, com potencial de doença ocupacional e caracterização de insalubridade. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir de imediato o uso do protetor auditivo na área mapeada; (ii) fornecer protetor com atenuação compatível com o nível medido e CA vigente, reforçando a orientação em DDS; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e confirmar o mapeamento de ruído da área, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em exposição solar prolongada e reiterada sem proteção, pelo caráter cumulativo do dano à pele.',
  texto_fundamentacao_normativa = 'O protetor solar deve estar disponível e em uso nas atividades a céu aberto, como medida de proteção contra a radiação solar. Aplica-se a NR-21 (trabalhos a céu aberto), que determina a adoção de medidas especiais de proteção dos trabalhadores contra a insolação. O critério "atividades a céu aberto (NR-21)" integra o plano de inspeção: a exposição solar direta e prolongada configura agente de risco à pele, e a disponibilização com reaplicação periódica é requisito verificável de aceitação da frente.',
  texto_risco_consequencia = 'A ausência de proteção solar em atividades a céu aberto expõe o trabalhador a queimaduras, envelhecimento precoce da pele e risco cumulativo de câncer de pele, além de insolação e desidratação. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) disponibilizar protetor solar de fator adequado nas frentes a céu aberto; (ii) orientar a aplicação no início da jornada e a reaplicação periódica, associada a sombreamento e hidratação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da disponibilização e do uso, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em áreas com tráfego intenso de veículos e máquinas, sobretudo em baixa luminosidade, sem o colete de alta visibilidade.',
  texto_fundamentacao_normativa = 'O colete refletivo de alta visibilidade é exigido em áreas com circulação de veículos e máquinas, para tornar o trabalhador conspícuo ao operador. Aplica-se a NR-18 quanto às medidas de sinalização e segurança na circulação de máquinas e veículos na obra, complementada pela análise de risco, pelo plano de sinalização viária da frente e pelas boas práticas de alta visibilidade. O critério "áreas com tráfego de veículos/máquinas" integra o plano de inspeção como requisito verificável, pois a visibilidade do pedestre é condição de segurança para o convívio com equipamentos móveis.',
  texto_risco_consequencia = 'A ausência de colete de alta visibilidade em área de tráfego reduz a percepção do trabalhador pelo operador, sobretudo em pontos cegos e baixa luminosidade, elevando o risco de atropelamento e prensamento com lesões graves ou fatais. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir o colete de alta visibilidade de todos os trabalhadores a pé na área de tráfego; (ii) reforçar a segregação física entre pedestres e equipamentos e a sinalização da frente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do uso e da sinalização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em exposição a fumos metálicos, sílica ou atmosferas com contaminante acima do limite, sem a máscara e o PPR aplicáveis.',
  texto_fundamentacao_normativa = 'A proteção respiratória deve ser a máscara correta para o agente (poeira, sílica ou fumos), gerida por Programa de Proteção Respiratória (PPR) quando aplicável. Aplicam-se a NR-06, quanto ao fornecimento do EPI, e a NR-15, quanto aos limites de tolerância para poeiras e fumos, decorrendo a seleção do respirador da avaliação de risco (PGR). O critério "máscara correta para poeira/fumos, com PPR quando aplicável" integra o plano de inspeção: um respirador de classe inadequada ou sem vedação não retém o contaminante, tornando o tipo e o ajuste requisitos de aceitação.',
  texto_risco_consequencia = 'Proteção respiratória ausente ou inadequada expõe o trabalhador à inalação de poeiras, sílica e fumos metálicos, com risco de pneumoconioses, silicose e intoxicação, doenças ocupacionais graves e por vezes irreversíveis. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a atividade geradora de contaminante até a proteção adequada; (ii) fornecer o respirador de classe correta com CA vigente, aplicando o teste de vedação e o PPR quando cabível; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica em todo trabalho em altura, pois a falha do cinturão em uma queda tem consequência potencialmente fatal.',
  texto_fundamentacao_normativa = 'O cinturão de segurança tipo paraquedista é EPI obrigatório para trabalho em altura, devendo estar íntegro e inspecionado antes do uso. Aplicam-se a NR-35 (trabalho em altura), que define o sistema de proteção contra quedas e a inspeção do equipamento, e a NR-06, quanto ao fornecimento; quando o sistema decorrer do projeto, o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, orienta os pontos e a solução de proteção. O critério "trabalho em altura, íntegro e inspecionado" integra o plano de inspeção e é requisito de aceitação: fitas, costuras e fivelas comprometidas invalidam a retenção da queda.',
  texto_risco_consequencia = 'Cinturão paraquedista danificado, mal vestido ou não inspecionado pode não reter a queda ou distribuir de forma inadequada a força de impacto, resultando em queda livre com lesões graves ou morte do trabalhador. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) proibir o acesso à altura até a regularização; (ii) liberar ou substituir o cinturão somente após inspeção formal (fitas, costuras, fivelas e argolas) por pessoa capacitada, com CA vigente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a ficha de inspeção do equipamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver fator de queda relevante, pois a ausência de absorvedor eleva a força de impacto a níveis lesivos.',
  texto_fundamentacao_normativa = 'O talabarte e o absorvedor de energia devem ser compatíveis com o plano de ancoragem, de modo a limitar a força de impacto e o fator de queda. Aplica-se a NR-35, que trata do sistema de ancoragem, dos conectores e da limitação da força de impacto no trabalho em altura; o dimensionamento e a localização dos pontos de ancoragem constam do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "compatíveis com o plano de ancoragem" integra o plano de inspeção: talabarte inadequado, sem absorvedor ou ancorado abaixo do nível correto compromete a zona livre de queda.',
  texto_risco_consequencia = 'Talabarte incompatível ou ausência de absorvedor de energia faz com que a força de impacto de uma queda ultrapasse o suportável pelo corpo, ou que a zona livre de queda seja insuficiente, resultando em choque contra estrutura ou solo, com lesão grave ou morte. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o trabalho em altura até a adequação do conjunto; (ii) substituir por talabarte com absorvedor de energia compatível com o plano de ancoragem e a zona livre de queda, verificando pontos e conectores, com CA vigente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a conferência do plano de ancoragem, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 11;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o dano ou o vencimento da vida útil comprometer EPI de proteção contra queda, choque ou agente insalubre.',
  texto_fundamentacao_normativa = 'Os EPIs devem estar sem danos, higienizados e dentro da vida útil, pois a proteção só é efetiva com o equipamento em condições de uso. Aplica-se a NR-06, que atribui ao empregador a responsabilidade pela guarda, conservação, higienização e substituição do EPI danificado ou extraviado. O critério "sem danos, higienizados, dentro da vida útil" integra o plano de inspeção: um EPI vencido, sujo ou avariado perde a capacidade de proteção e deixa de atender à condição de aceitação, ainda que fisicamente presente.',
  texto_risco_consequencia = 'EPI danificado, contaminado ou com vida útil vencida deixa de oferecer a proteção esperada, expondo o trabalhador ao risco original — impacto, queda, agente químico ou biológico — e podendo provocar dermatoses pela má higienização. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher e descartar os EPIs danificados ou vencidos, impedindo seu uso; (ii) substituir por unidades íntegras e higienizadas, dentro da vida útil e com CA vigente, e implantar rotina de inspeção periódica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a ficha de EPI, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 12;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o EPI de CA vencido ou ilegível for destinado a risco grave e iminente (altura, elétrico, respiratório).',
  texto_fundamentacao_normativa = 'Todo EPI deve possuir Certificado de Aprovação (CA) vigente e legível, emitido pelo órgão nacional competente, como comprovação de que o equipamento foi ensaiado e aprovado para o risco a que se destina. Aplica-se a NR-06, que veda o uso e a comercialização de EPI sem CA válido e responsabiliza o empregador por exigir apenas equipamento certificado. O critério "Certificado de Aprovação vigente e legível" integra o plano de inspeção: CA vencido ou ilegível impede a rastreabilidade e a certificação da proteção, sendo requisito documental de aceitação.',
  texto_risco_consequencia = 'EPI com CA vencido ou ilegível não tem sua eficácia de proteção assegurada nem comprovada, podendo falhar diante do risco real e expondo o trabalhador a lesões, além de configurar não conformidade legal com penalização à obra. A permanência da condição mantém a exposição ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso os EPIs com CA vencido ou ilegível; (ii) substituir por equipamentos com CA vigente e legível, conferindo a validade na base oficial e a adequação ao risco; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do EPI e do respectivo CA, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 13;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de ficha assinada acompanhar uso irregular ou recusa de EPI, comprometendo a rastreabilidade da proteção.',
  texto_fundamentacao_normativa = 'A entrega de EPI deve ser formalizada em ficha assinada e atualizada, comprovando o fornecimento, a orientação e a responsabilidade pelo uso. Aplica-se a NR-06, que obriga o empregador a fornecer o EPI gratuitamente, treinar quanto ao uso e manter registro/comprovante de entrega. O critério "ficha de EPI assinada e atualizada" integra o plano de inspeção como requisito documental de aceitação: sem o registro, não há rastreabilidade de qual EPI foi entregue, quando e a quem, nem prova da orientação prestada.',
  texto_risco_consequencia = 'A falta de ficha de entrega assinada e atualizada impede comprovar o fornecimento e a orientação de uso do EPI, fragilizando a gestão de SST e a defesa da obra e sinalizando possível deficiência no controle de distribuição da proteção. A permanência da condição mantém a lacuna documental ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os trabalhadores com ficha de EPI ausente, incompleta ou desatualizada; (ii) regularizar as fichas, colhendo assinatura na entrega e registrando a orientação de uso, com controle de reposição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) ou digitalização das fichas regularizadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-02' and item_numero = 14;

-- ST-03 (13 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de identificação impedir o bloqueio seguro da fonte correta durante intervenção em circuito energizado ou próximo a partes vivas',
  texto_fundamentacao_normativa = 'A identificação legível e inequívoca de painéis, disjuntores e circuitos é condição para a operação e a manutenção seguras da instalação, permitindo a correta seleção da fonte a ser desenergizada e bloqueada. Aplica-se a NR-10 (Segurança em Instalações e Serviços em Eletricidade), que exige instalações elétricas mantidas em condições seguras e o prontuário com esquemas atualizados, e a NBR 5410 (instalações elétricas de baixa tensão), que determina a identificação dos circuitos nos dispositivos de proteção e manobra. O critério "Identificação legível de painéis, disjuntores e circuitos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, em consonância com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'A falta de identificação legível de painéis e circuitos induz manobra em fonte incorreta, deixa circuitos supostamente desligados ainda energizados e eleva o risco de choque elétrico, arco e acionamento indevido durante manutenção, com potencial de acidente grave e interrupção não planejada de sistemas. A permanência da condição mantém latente o erro de manobra até a efetiva regularização da identificação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear painéis, disjuntores e circuitos confrontando o campo com o diagrama unifilar e o projeto executivo aprovado; (ii) aplicar etiquetas/plaquetas de identificação duráveis, legíveis e resistentes ao ambiente, em cada dispositivo de proteção e manobra; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualização do prontuário, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — bloqueio e etiquetagem (LOTO) é medida de controle da desenergização; sua ausência configura exposição direta a risco de morte e não admite início ou continuidade do serviço',
  texto_fundamentacao_normativa = 'O bloqueio e etiquetagem (Lockout/Tagout) garante o impedimento de reenergização enquanto houver trabalhadores expostos, materializando a etapa da desenergização exigida pela NR-10 (Segurança em Instalações e Serviços em Eletricidade), que determina seccionamento, impedimento de reenergização e sinalização da condição de bloqueio. O uso de cadeados individuais assegura que somente o próprio executante remova seu bloqueio, e a etiqueta comunica a condição e o responsável. O critério "Cadeados individuais e etiquetas aplicados nas fontes de energia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'A ausência de cadeados individuais e etiquetas nas fontes de energia permite reenergização acidental ou por terceiros durante a intervenção, expondo o trabalhador a choque elétrico e arco com risco de fatalidade. A permanência da condição mantém a fonte passível de reativação não controlada enquanto perdurar o serviço. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper imediatamente a atividade e promover o seccionamento da fonte correta; (ii) aplicar cadeado individual de cada executante e etiqueta com identificação do responsável, data e motivo, em dispositivo de bloqueio adequado, garantindo o impedimento de reenergização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do conjunto de bloqueio instalado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a verificação de ausência de tensão é etapa obrigatória da sequência de desenergização; iniciar o serviço sem ela pressupõe circuito energizado e caracteriza risco iminente',
  texto_fundamentacao_normativa = 'O teste de ausência de tensão com detector apropriado, imediatamente antes do início dos serviços, confirma que o seccionamento e o bloqueio foram efetivos e que o circuito está de fato desenergizado. Integra a sequência de desenergização preconizada pela NR-10 (Segurança em Instalações e Serviços em Eletricidade), realizada nos condutores e partes a serem tocados, com instrumento previamente testado em fonte conhecida. O critério "Teste com detector antes do início dos serviços" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, indissociável das demais etapas de bloqueio e aterramento.',
  texto_risco_consequencia = 'Iniciar o trabalho sem verificar a ausência de tensão pressupõe indevidamente que o circuito está desligado, expondo o trabalhador a contato com parte viva por falha de manobra, retorno de tensão ou fonte não identificada, com risco de choque e arco elétrico de consequência grave a fatal. A permanência da condição mantém a incerteza sobre o estado energético do circuito. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o serviço e executar o teste de ausência de tensão com detector adequado à classe de tensão, testado antes e depois em fonte conhecida; (ii) somente prosseguir após confirmação da ausência de tensão em todos os condutores e partes a serem manuseados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da verificação e do instrumento utilizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o aterramento temporário protege contra reenergização e tensões induzidas; sua ausência em circuito sob intervenção mantém exposição a risco de morte',
  texto_fundamentacao_normativa = 'O conjunto de aterramento temporário, aplicado após a confirmação de ausência de tensão, escoa eventuais reenergizações, cargas residuais e tensões induzidas, protegendo o trabalhador durante a intervenção. Compõe a etapa de instalação de aterramento temporário prevista na NR-10 (Segurança em Instalações e Serviços em Eletricidade) e no procedimento de trabalho da obra, que definem sua aplicação conforme a classe de tensão e a configuração do circuito. O critério "Conjunto de aterramento aplicado conforme procedimento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'A não instalação do aterramento temporário deixa o trabalhador sem proteção contra reenergização acidental e contra tensões induzidas por circuitos adjacentes energizados, elevando o risco de choque elétrico e arco durante o serviço. A permanência da condição mantém desprotegida a zona de trabalho enquanto durar a intervenção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar o conjunto de aterramento temporário dimensionado para a classe de tensão e a corrente de curto-circuito do trecho, conectando primeiro ao ponto de terra; (ii) posicionar o aterramento entre o local de trabalho e as possíveis fontes, conforme o procedimento aprovado, mantendo-o durante toda a intervenção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do conjunto instalado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver partes vivas acessíveis sem isolação/barreira e a distância de segurança não puder ser mantida pela equipe',
  texto_fundamentacao_normativa = 'O isolamento das partes vivas, a instalação de barreiras/anteparos e a observância das distâncias de segurança evitam o contato acidental e a aproximação indevida a elementos energizados nas atividades que não permitem desenergização plena. Tais medidas de proteção coletiva são exigidas pela NR-10 (Segurança em Instalações e Serviços em Eletricidade), que estabelece o isolamento das partes vivas, a sinalização e as distâncias mínimas em função da tensão. O critério "Partes vivas isoladas/sinalizadas, distâncias de segurança" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'Partes vivas expostas sem isolação, barreiras ou sinalização, ou com invasão da distância de segurança, expõem trabalhadores e transeuntes a contato direto e a arco por aproximação, com risco de choque elétrico e queimaduras graves. A permanência da condição mantém acessível a zona energizada até a implantação das barreiras. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) isolar as partes vivas com coberturas/mantas isolantes adequadas à tensão e instalar barreiras físicas e sinalização de advertência; (ii) delimitar e respeitar as distâncias de segurança em função da tensão, controlando o acesso à zona de risco; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das barreiras e da sinalização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ferramenta com isolação danificada for utilizada em trabalho sob tensão ou nas proximidades de partes vivas',
  texto_fundamentacao_normativa = 'As ferramentas manuais com isolação íntegra e certificada para a classe de tensão são a última barreira contra o contato acidental durante o manuseio próximo a partes energizadas, e sua integridade deve ser inspecionada antes do uso. A NR-10 (Segurança em Instalações e Serviços em Eletricidade) exige ferramental e equipamentos apropriados e em condições adequadas ao serviço elétrico; a certificação e o ensaio da isolação da ferramenta devem atender à especificação do fabricante e ao procedimento da obra. O critério "Ferramental com isolação íntegra e certificada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'O uso de ferramentas com isolação trincada, ressecada, perfurada ou sem certificação para a tensão de trabalho anula a proteção esperada e pode conduzir corrente ao operador em caso de toque em parte viva, resultando em choque elétrico e arco. A permanência da condição mantém em circulação ferramental impróprio para a atividade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher e segregar as ferramentas com isolação comprometida ou sem certificação; (ii) disponibilizar ferramental isolado íntegro, certificado e compatível com a classe de tensão, com inspeção visual registrada antes do uso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do ferramental aprovado e da respectiva certificação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver nenhum extintor de classe compatível acessível na frente de serviço elétrico energizado',
  texto_fundamentacao_normativa = 'A disponibilidade de extintor adequado a incêndios em equipamentos energizados (agente CO2 ou pó BC/ABC), próximo e acessível à atividade, permite o combate imediato a princípio de incêndio de origem elétrica sem risco de choque ao operador. A exigência de proteção contra incêndio e de meios de combate compatíveis com a natureza do risco decorre da NR-23 (Proteção Contra Incêndios) e do plano de emergência da obra, observada a classe de fogo envolvida. O critério "CO2 ou pó BC próximo à atividade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'A inexistência ou o posicionamento distante de extintor de classe adequada retarda ou impede o combate a princípio de incêndio em painel ou equipamento energizado, permitindo a propagação do fogo e o uso de agente inadequado (água/espuma) com risco adicional de choque ao operador. A permanência da condição mantém a frente de serviço sem meio de combate compatível. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) posicionar extintor de CO2 ou pó (BC/ABC) adequado a fogo em equipamento energizado, próximo e sinalizado na frente de serviço; (ii) verificar carga, lacre, validade e acessibilidade do extintor, garantindo desobstrução; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do extintor posicionado e de sua etiqueta de inspeção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de delimitação permitir a circulação de terceiros dentro da zona de risco elétrico ou de arco',
  texto_fundamentacao_normativa = 'O isolamento físico da área e a instalação de placas de advertência impedem o acesso de pessoas não autorizadas à zona de risco elétrico e comunicam o perigo, protegendo transeuntes e demais equipes da obra. A sinalização e o controle de acesso às áreas de serviço elétrico são requeridos pela NR-10 (Segurança em Instalações e Serviços em Eletricidade), complementada pela NR-26 (Sinalização de Segurança) quanto às cores e placas de advertência. O critério "Isolamento físico e placas de advertência" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'A área de serviço elétrico sem isolamento físico e sem placas de advertência permite a aproximação e a passagem de pessoas não autorizadas junto a partes energizadas ou à zona de arco, elevando o risco de choque, queimaduras e atropelamento de tarefa. A permanência da condição mantém a frente exposta à circulação indevida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) delimitar a área com barreiras físicas (cavaletes, fitas/telas ou grades) controlando pontos de acesso; (ii) instalar placas de advertência de risco elétrico visíveis nos limites da zona isolada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do isolamento e da sinalização implantados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a execução de serviço elétrico por profissional sem autorização formal e treinamento exigido caracteriza descumprimento direto de requisito legal e não admite continuidade',
  texto_fundamentacao_normativa = 'Somente trabalhador habilitado, qualificado, capacitado e formalmente autorizado pode intervir em instalações elétricas, condição que assegura a competência técnica e o conhecimento dos riscos e das medidas de controle. A NR-10 (Segurança em Instalações e Serviços em Eletricidade) exige treinamento específico e autorização formal do trabalhador, com curso complementar de Segurança em Sistema Elétrico de Potência (SEP) e suas proximidades quando a atividade assim o exigir. O critério "Autorização formal + treinamento NR-10 (e SEP quando aplicável)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'Permitir a intervenção de profissional sem autorização formal e sem o treinamento NR-10/SEP aplicável coloca em risco quem desconhece os procedimentos de segurança e os riscos elétricos, elevando a probabilidade de erro de manobra, choque e arco, além de expor a obra a responsabilização legal. A permanência da condição mantém pessoa não autorizada atuando na frente elétrica. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar imediatamente o profissional não autorizado da atividade elétrica; (ii) comprovar treinamento NR-10 válido (e SEP quando aplicável) e emitir/atualizar a autorização formal antes de qualquer nova intervenção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos certificados e da autorização formal arquivados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — vestimenta antichama com ATPV incompatível com o estudo de arco expõe o trabalhador a queimadura de segundo grau na ocorrência de arco, sem proteção efetiva',
  texto_fundamentacao_normativa = 'A vestimenta resistente à chama com desempenho térmico (ATPV) igual ou superior à energia incidente prevista protege o trabalhador contra queimaduras em caso de arco elétrico, devendo a categoria de risco ser definida pelo estudo de arco da instalação. A NR-10 (Segurança em Instalações e Serviços em Eletricidade) exige vestimentas adequadas às atividades com risco de arco, dimensionadas conforme a análise de risco/estudo de energia incidente. O critério "ATPV compatível com o estudo de arco/categoria de risco" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'O uso de vestimenta com ATPV inferior à energia incidente do ponto, ou de tecido não antichama, deixa o trabalhador exposto a queimaduras graves e à ignição da roupa na ocorrência de arco elétrico, com consequências potencialmente fatais. A permanência da condição mantém a equipe subprotegida frente ao risco de arco. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consultar o estudo de arco/energia incidente do ponto e definir a categoria de risco e o ATPV mínimo requerido; (ii) substituir a vestimenta por conjunto antichama certificado com ATPV igual ou superior ao exigido, incluindo os demais EPIs associados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da vestimenta e de sua etiqueta de ATPV, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a desatualização ou indisponibilidade do PIE impedir a análise de risco e o planejamento seguro da intervenção elétrica',
  texto_fundamentacao_normativa = 'O Prontuário das Instalações Elétricas (PIE) reúne os documentos, procedimentos, laudos e esquemas que suportam a operação e a manutenção seguras da instalação, devendo estar atualizado e disponível aos envolvidos. A NR-10 (Segurança em Instalações e Serviços em Eletricidade) determina que o estabelecimento mantenha o prontuário atualizado, com o conjunto de documentos previstos, à disposição da fiscalização e dos trabalhadores. O critério "Atualizado e disponível" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'O PIE desatualizado ou indisponível priva a equipe das informações necessárias ao planejamento da intervenção, à análise de risco e à identificação de circuitos e proteções, aumentando a chance de erro de manobra e de exposição a riscos não mapeados. A permanência da condição mantém a instalação sem base documental confiável para os serviços. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reunir e atualizar os documentos que compõem o PIE (procedimentos, laudos, esquemas, certificações e autorizações); (ii) disponibilizar o prontuário, físico ou digital, de forma acessível aos trabalhadores e à fiscalização na frente de serviço; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do prontuário atualizado e disponível, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 11;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a divergência entre o unifilar e o campo puder induzir manobra em circuito incorreto durante o bloqueio',
  texto_fundamentacao_normativa = 'Os diagramas unifilares atualizados e fiéis ao campo permitem compreender a topologia da instalação, identificar fontes e proteções e planejar corretamente as manobras de seccionamento e bloqueio. Integram o prontuário exigido pela NR-10 (Segurança em Instalações e Serviços em Eletricidade), que requer esquemas unifilares atualizados, e refletem a concepção da NBR 5410 (instalações elétricas de baixa tensão) e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Atualizados e correspondentes ao campo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'Diagramas unifilares desatualizados ou divergentes do campo induzem a identificação errada de circuitos e fontes, levando a manobras em disjuntor incorreto e à falsa percepção de desenergização, com risco de choque e arco durante a intervenção. A permanência da condição mantém a documentação em desacordo com a instalação real. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar os diagramas unifilares com a instalação em campo, levantando as divergências; (ii) revisar e atualizar os unifilares para refletir a configuração real, compatibilizando-os com o projeto executivo aprovado e o prontuário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos diagramas revisados e disponíveis na frente de serviço, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 12;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o valor de resistência de aterramento estiver fora do limite de projeto ou o laudo vencido em instalação já energizada',
  texto_fundamentacao_normativa = 'As medições de resistência de aterramento comprovam a eficácia do escoamento de correntes de falta e de descargas atmosféricas, condição essencial para a atuação das proteções e para a segurança das pessoas. Os laudos de SPDA e de malha de terra devem observar a NBR 5419 (proteção contra descargas atmosféricas) quanto ao SPDA e a NBR 5410 (instalações elétricas de baixa tensão) quanto ao aterramento, mantendo-se dentro dos valores e da validade estabelecidos em projeto. O critério "Laudos SPDA/malha dentro da validade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da atividade.',
  texto_risco_consequencia = 'Resistência de aterramento acima do limite de projeto, ou laudo vencido, compromete o escoamento de correntes de falta e de descargas atmosféricas, reduzindo a eficácia das proteções e elevando o risco de tensões de toque/passo perigosas, choque elétrico e danos por surto. A permanência da condição mantém a instalação sem comprovação válida de aterramento adequado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar/reexecutar as medições de resistência de aterramento da malha e do SPDA por profissional habilitado, com instrumento calibrado; (ii) tratar as não conformidades (revisão de conexões, hastes/eletrodos adicionais ou tratamento de solo) até enquadrar os valores no limite de projeto e emitir laudo válido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das medições e anexar o laudo atualizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-03' and item_numero = 13;

-- ST-04 (13 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que o içamento for classificado como crítico (carga próxima da capacidade, próxima a linhas energizadas, sobre áreas ocupadas ou com dois equipamentos); rebaixar a Maior apenas em içamentos rotineiros de baixo risco sem plano formalizado.',
  texto_fundamentacao_normativa = 'Todo içamento crítico deve ser precedido de plano de rigging que defina configuração de equipamento, acessórios, ângulos de estropos, capacidades e sequência da operação, elaborado e assinado por profissional legalmente habilitado com a respectiva anotação de responsabilidade técnica. Aplicam-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais) e a NR-18 (segurança na indústria da construção), que exigem o planejamento das operações de movimentação de cargas, bem como o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quando o içamento envolver montagem de peças estruturais. O critério "içamentos críticos com plano assinado por profissional habilitado" integra o plano de inspeção da obra e constitui requisito verificável de liberação da operação.',
  texto_risco_consequencia = 'Executar içamento crítico sem plano de rigging aprovado remove a análise prévia de capacidades, ângulos e trajetória, expondo a operação a tombamento do equipamento, ruptura de acessórios e queda de carga sobre pessoas e estruturas, com potencial de acidente fatal e paralisação da obra. A permanência da condição mantém a operação sem controle de engenharia até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender imediatamente o içamento crítico até a emissão do plano de rigging; (ii) elaborar e aprovar o plano com profissional habilitado, contemplando configuração, acessórios, capacidades e sequência, com anotação de responsabilidade técnica; (iii) evidenciar a correção com registro fotográfico do plano assinado e da liberação em campo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica se o operador estiver conduzindo a máquina sem habilitação/autorização ou com ASO vencido; rebaixar a Maior apenas quando houver habilitação válida e a pendência for exclusivamente documental (autorização formal não anexada).',
  texto_fundamentacao_normativa = 'O operador de equipamento de içamento deve possuir habilitação e certificação compatíveis com o equipamento operado, autorização formal do empregador e Atestado de Saúde Ocupacional (ASO) válido que ateste aptidão para a função. Aplicam-se a NR-11 e a NR-12 (segurança no trabalho em máquinas e equipamentos), que condicionam a operação a trabalhador capacitado e autorizado, e a NR-07, que disciplina o ASO. O critério "CNH/certificação compatível com o equipamento, ASO válido" integra o plano de inspeção da obra e constitui requisito verificável de aptidão do operador.',
  texto_risco_consequencia = 'Permitir a operação por profissional não habilitado, não autorizado ou com aptidão de saúde não comprovada eleva a probabilidade de manobra incorreta, sobrecarga e perda de controle da carga suspensa, com risco de acidente grave a terceiros e ao próprio operador, além de descaracterizar a regularidade legal da operação. A permanência da condição mantém a operação sob responsável não qualificado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar o operador da função até a comprovação dos requisitos; (ii) regularizar habilitação/certificação compatível com o equipamento, autorização formal e ASO válido, designando operador apto; (iii) evidenciar a correção com registro fotográfico dos documentos e da autorização ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o içamento ocorrer com carga sobre áreas de circulação, sem contato visual direto operador-carga, ou em manobras de precisão que dependam integralmente da sinalização.',
  texto_fundamentacao_normativa = 'A operação de içamento deve contar com sinaleiro/amarrador treinado, presente, identificado e apto a estabelecer comunicação eficaz com o operador, responsável pela amarração da carga e pela orientação das manobras. Aplicam-se a NR-11 e a NR-18, que exigem trabalhador capacitado para a movimentação de cargas e a definição de responsável pela sinalização, sendo boa prática consagrada que apenas um sinaleiro comande a operação por vez. O critério "presente, identificado e com comunicação eficaz" integra o plano de inspeção da obra e constitui requisito verificável da operação de içamento.',
  texto_risco_consequencia = 'A ausência de sinaleiro treinado, sua não identificação ou falha de comunicação com o operador levam a manobras sem orientação segura, colisão da carga com estruturas e trabalhadores e movimentação errática, com risco de esmagamento e queda de carga. A permanência da condição mantém a operação sem coordenação de manobra até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) designar sinaleiro/amarrador treinado, identificado por colete ou braçadeira distintiva, único a comandar a manobra; (ii) confirmar treinamento e o código de sinais padronizado antes da liberação, garantindo comunicação eficaz; (iii) evidenciar a correção com registro fotográfico do sinaleiro identificado em posição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando o peso da carga for desconhecido ou estimado, ou quando se aproximar/exceder a capacidade da tabela de carga na configuração adotada; rebaixar a Maior apenas com margem confortável de capacidade e peso conhecido pendente apenas de registro.',
  texto_fundamentacao_normativa = 'A carga a ser içada deve ter peso conhecido e identificado, comprovadamente igual ou inferior à capacidade indicada na tabela de carga do equipamento para o raio e a configuração de trabalho, considerando o peso dos acessórios de içamento. Aplicam-se a NR-11 e a NR-12, que vedam a operação acima da capacidade nominal e exigem a observância das especificações do fabricante. O critério "peso conhecido ≤ capacidade da tabela de carga" integra o plano de inspeção da obra e constitui requisito verificável de aceitação do içamento.',
  texto_risco_consequencia = 'Içar carga de peso desconhecido ou superior à capacidade da tabela de carga provoca sobrecarga do equipamento e dos acessórios, com risco direto de tombamento do guindaste, ruptura de cabos e queda da carga, configurando cenário de acidente catastrófico. A permanência da condição mantém a operação em regime de sobrecarga potencial até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o içamento até a determinação do peso real da carga por pesagem, célula de carga ou memória de cálculo; (ii) confrontar o peso, acrescido dos acessórios, com a tabela de carga para o raio e a configuração, redefinindo o equipamento se necessário; (iii) evidenciar a correção com registro fotográfico da pesagem e da tabela de carga aplicada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica na presença de gaiola de passarinho, fios rompidos acima do critério de descarte, corrosão acentuada ou amassamento; rebaixar a Maior apenas em desgaste incipiente sem atingir critério de descarte, com substituição programada.',
  texto_fundamentacao_normativa = 'Os cabos de aço utilizados no içamento devem estar íntegros, sem formação de gaiola de passarinho, fios rompidos além do critério de descarte, corrosão, amassamento ou redução de diâmetro, condição verificada por inspeção antes do uso. Aplica-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais), que exige a inspeção e a manutenção em condições seguras dos cabos e acessórios de movimentação de cargas, com a substituição de componentes deteriorados, complementada pelos critérios de descarte definidos pelo fabricante. O critério "sem gaiola, fios rompidos ou corrosão" integra o plano de inspeção da obra e constitui requisito verificável de aceitação dos acessórios.',
  texto_risco_consequencia = 'Utilizar cabo de aço com gaiola, fios rompidos ou corrosão reduz drasticamente a carga de ruptura efetiva do acessório, podendo romper sob carga e provocar queda abrupta da carga suspensa sobre pessoas e estruturas. A permanência da condição mantém em serviço um acessório com resistência comprometida até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar imediatamente de uso o cabo de aço reprovado, segregando-o para descarte; (ii) substituí-lo por cabo íntegro de capacidade compatível, inspecionado e aprovado antes do uso; (iii) evidenciar a correção com registro fotográfico do cabo substituído e da inspeção ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando houver corte, abrasão profunda, dano por calor/químico ou etiqueta de capacidade ilegível/ausente que impeça a identificação da capacidade; rebaixar a Maior apenas em sujidade superficial sem comprometimento estrutural, com etiqueta legível.',
  texto_fundamentacao_normativa = 'As cintas têxteis de içamento devem estar íntegras, sem cortes, abrasão, danos por calor ou agentes químicos, e com etiqueta de identificação legível informando a capacidade e o fator de segurança. Aplica-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais), que exige acessórios de movimentação em condições seguras e devidamente identificados, sendo boa prática consagrada o descarte imediato de cinta sem etiqueta legível, pois não se pode atestar sua capacidade. O critério "etiqueta de capacidade legível, sem cortes/abrasão" integra o plano de inspeção da obra e constitui requisito verificável de aceitação dos acessórios.',
  texto_risco_consequencia = 'Empregar cinta cortada, abrasada ou sem etiqueta legível significa operar com capacidade desconhecida ou resistência reduzida, com risco de ruptura da cinta e queda da carga, além de impossibilitar a correta seleção do acessório para o peso a içar. A permanência da condição mantém em serviço acessório não confiável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso e segregar para descarte a cinta danificada ou sem etiqueta legível; (ii) substituí-la por cinta íntegra, com etiqueta de capacidade legível e compatível com a carga; (iii) evidenciar a correção com registro fotográfico da cinta aprovada e de sua etiqueta ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica na utilização de manilha com pino incorreto/improvisado, sem identificação de capacidade ou com deformação; rebaixar a Maior apenas quando a capacidade estiver identificada e a pendência for de registro documental do certificado.',
  texto_fundamentacao_normativa = 'As manilhas e demais acessórios de içamento devem ser certificados, com capacidade de carga (WLL) gravada e identificável, utilizados com o pino original correto e livres de deformação, desgaste ou corrosão. Aplica-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais), que exige acessórios de movimentação seguros, íntegros e adequados à carga, complementada pelas especificações e pela certificação do fabricante. O critério "pino correto, capacidade identificada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação dos acessórios.',
  texto_risco_consequencia = 'Empregar manilha não certificada, sem capacidade identificada ou com pino improvisado gera ponto frágil no conjunto de içamento, sujeito a abertura do corpo ou saída do pino sob carga, com queda da carga e risco de acidente grave. A permanência da condição mantém no circuito de carga um elemento de resistência não comprovada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso a manilha/acessório sem certificação, sem identificação ou com pino incorreto; (ii) substituí-la por acessório certificado, com capacidade gravada e pino original correto, compatível com a carga; (iii) evidenciar a correção com registro fotográfico do acessório certificado e da marcação de capacidade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando a trava de segurança do gancho estiver ausente, inoperante ou o gancho apresentar deformação/abertura de garganta; rebaixar a Maior apenas em desgaste leve da trava com funcionamento ainda assegurado, com reparo programado.',
  texto_fundamentacao_normativa = 'O gancho de içamento deve dispor de trava de segurança funcional que impeça o escape acidental do acessório, estando livre de deformação, trincas ou abertura de garganta além do limite admissível. Aplica-se a NR-11 (transporte, movimentação, armazenagem e manuseio de materiais), que exige acessórios de movimentação de cargas em condições seguras e dotados de dispositivos que impeçam o escape acidental da carga, complementada pelos critérios do fabricante. O critério "trava funcional, sem deformação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação do acessório.',
  texto_risco_consequencia = 'Operar com gancho sem trava funcional ou deformado permite que estropos e cintas escapem da garganta durante a manobra, resultando em queda súbita da carga; a abertura de garganta indica sobrecarga pretérita e ruptura iminente. A permanência da condição mantém a carga sem retenção segura no gancho até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o uso do gancho com trava inoperante ou deformação; (ii) restabelecer ou substituir a trava de segurança e, havendo deformação/abertura de garganta, substituir o gancho por unidade certificada; (iii) evidenciar a correção com registro fotográfico do gancho com trava funcional ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver pessoas sob a carga suspensa ou dentro do raio de giro; rebaixar a Maior apenas quando o isolamento existir mas apresentar falhas pontuais de sinalização, sem trânsito de pessoas na zona de risco.',
  texto_fundamentacao_normativa = 'A área de içamento deve ser previamente isolada e sinalizada, com delimitação do raio de giro do equipamento e da projeção da carga, sendo proibida a permanência ou o trânsito de pessoas sob carga suspensa. Aplicam-se a NR-11 e a NR-18, que exigem a interdição da área de movimentação de cargas e a proibição de circulação sob cargas suspensas. O critério "ninguém sob carga suspensa; raio de giro delimitado" integra o plano de inspeção da obra e constitui requisito verificável de controle da operação.',
  texto_risco_consequencia = 'A falta de isolamento da área de içamento expõe trabalhadores à queda de carga, ao contato com o contrapeso em rotação e ao esmagamento pelo raio de giro do equipamento, cenários de elevado potencial de lesão grave ou fatal. A permanência da condição mantém pessoas expostas na zona de risco até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a operação até o completo isolamento da área; (ii) delimitar e sinalizar o raio de giro e a projeção da carga com barreiras físicas e vigilância, removendo pessoas da zona de risco; (iii) evidenciar a correção com registro fotográfico do isolamento implantado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a operação ocorrer sem contato visual entre operador e carga ou em ambiente ruidoso que dependa exclusivamente de comunicação por rádio sem redundância.',
  texto_fundamentacao_normativa = 'A comunicação entre operador e sinaleiro deve ser assegurada por meio confiável — rádio dedicado ou código de sinais manuais padronizado e previamente combinado — garantindo o entendimento inequívoco das manobras e a existência de sinal de parada de emergência reconhecível por qualquer pessoa. Aplicam-se a NR-11 e a NR-18, que exigem coordenação segura das operações de movimentação de cargas. O critério "rádio ou sinais padronizados" integra o plano de inspeção da obra e constitui requisito verificável da operação de içamento.',
  texto_risco_consequencia = 'A comunicação deficiente ou não padronizada entre operador e sinaleiro gera interpretação equivocada de comandos, movimentos inesperados da carga e impossibilidade de parada imediata em emergência, com risco de colisão e queda de carga. A permanência da condição mantém a manobra sujeita a erro de comando até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir e testar o meio de comunicação (rádio em canal exclusivo ou código de sinais padronizado) antes de cada operação; (ii) estabelecer que qualquer sinal duvidoso e o comando de parada interrompem imediatamente a manobra; (iii) evidenciar a correção com registro fotográfico dos equipamentos de comunicação e do código de sinais afixado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando o içamento prosseguir com velocidade de vento acima do limite do fabricante ou sem monitoramento; rebaixar a Maior apenas quando houver anemômetro/monitoramento ativo e a operação estiver dentro do limite, pendente o registro.',
  texto_fundamentacao_normativa = 'As condições de vento devem ser monitoradas durante o içamento e a operação suspensa sempre que a velocidade ultrapassar o limite estabelecido pelo fabricante para o equipamento e a configuração de carga, considerando ainda o efeito de vela em cargas de grande área. Aplicam-se a NR-11 e a NR-12, que exigem a observância das condições operacionais e dos limites definidos pelo fabricante do equipamento. O critério "içamento suspenso acima do limite do fabricante" integra o plano de inspeção da obra e constitui requisito verificável de segurança da operação.',
  texto_risco_consequencia = 'Realizar içamento com vento acima do limite do fabricante provoca oscilação e giro descontrolado da carga, aumento dos esforços sobre a lança e risco de tombamento do equipamento, especialmente com peças de grande superfície exposta. A permanência da condição mantém a operação sujeita a esforços não previstos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) monitorar continuamente a velocidade do vento com anemômetro na frente de serviço; (ii) suspender o içamento ao atingir o limite do fabricante, pousando a carga em local seguro, e definir cabos-guia (tag lines) para controle de oscilação quando permitido; (iii) evidenciar a correção com registro fotográfico da medição de vento e do procedimento de suspensão ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 11;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando faltar checklist diário ou o laudo/inspeção periódica estiver vencido ou reprovado; rebaixar a Maior apenas quando o equipamento estiver em conformidade e a pendência for exclusivamente de arquivamento do registro.',
  texto_fundamentacao_normativa = 'O equipamento de içamento (guindaste, caminhão munck, plataforma elevatória - MEWP) deve ser submetido a checklist diário pré-operacional e a inspeções/laudos periódicos com validade vigente, elaborados por profissional habilitado, atestando as condições de segurança de estruturas, cabos, freios e dispositivos limitadores. Aplicam-se a NR-11, a NR-12 e a NR-18, que exigem inspeção periódica e manutenção dos equipamentos de movimentação de cargas, com registro documentado. O critério "checklist diário + inspeção/laudo periódico" integra o plano de inspeção da obra e constitui requisito verificável de liberação do equipamento.',
  texto_risco_consequencia = 'Operar equipamento sem checklist diário ou com laudo periódico vencido significa utilizar máquina cujas condições de freios, dispositivos de segurança e integridade estrutural não estão comprovadas, elevando o risco de falha mecânica súbita e perda de controle da carga. A permanência da condição mantém em serviço equipamento sem aptidão comprovada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar o equipamento de operação até a regularização; (ii) executar o checklist diário e providenciar a inspeção/laudo periódico por profissional habilitado, corrigindo as não conformidades apontadas; (iii) evidenciar a correção com registro fotográfico do checklist preenchido e do laudo vigente ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 12;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando as patolas não estiverem totalmente estendidas, sem pranchas de apoio dimensionadas, sobre solo não compactado ou com o equipamento fora de nível; rebaixar a Maior apenas em pequeno desnível corrigível sem risco de recalque, com apoio adequado.',
  texto_fundamentacao_normativa = 'O equipamento deve ser patolado com as sapatas totalmente estendidas sobre pranchas/placas de apoio dimensionadas para distribuir a pressão ao solo, com o terreno compactado e capaz de suportar as reações de apoio, e o conjunto perfeitamente nivelado antes do içamento. Aplicam-se a NR-11 e a NR-12, que exigem a operação em condições de estabilidade e conforme as instruções do fabricante, subsidiadas pela verificação da capacidade de suporte do solo em projeto ou sondagem quando aplicável. O critério "solo compactado, pranchas de apoio, equipamento nivelado" integra o plano de inspeção da obra e constitui requisito verificável de estabilidade da operação.',
  texto_risco_consequencia = 'Patolamento inadequado, pranchas insuficientes ou solo sem capacidade de suporte provocam recalque de uma das sapatas e desnivelamento do equipamento sob carga, condição que precede o tombamento do guindaste, um dos cenários mais graves na movimentação de cargas. A permanência da condição mantém o equipamento em base instável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a operação e reavaliar a base de apoio; (ii) estender totalmente as patolas sobre pranchas/placas dimensionadas, garantir a compactação/capacidade do solo e nivelar o equipamento conforme o indicador de nível; (iii) evidenciar a correção com registro fotográfico do patolamento com apoios e do nivelamento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-04' and item_numero = 13;

-- ST-05 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a proteção ausente ou inoperante exponha zona de prensagem, corte ou partes móveis com risco de amputação, ou quando o intertravamento estiver anulado/burlado.',
  texto_fundamentacao_normativa = 'O enclausuramento das partes móveis por proteções fixas e móveis, associado a intertravamentos que impeçam o funcionamento com a proteção aberta, é requisito de segurança na operação de máquinas e equipamentos, disciplinado pela NR-12 (Segurança no Trabalho em Máquinas e Equipamentos). O critério "Partes móveis enclausuradas, intertravamentos funcionais" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, devendo as proteções resistir aos esforços a que estão sujeitas e não criar novos riscos. A conformidade deve observar, ainda, o manual do fabricante e as especificações do equipamento.',
  texto_risco_consequencia = 'A operação de máquina com proteção ausente, danificada ou com intertravamento burlado expõe o trabalhador ao contato com partes móveis, com risco de esmagamento, corte, amputação ou aprisionamento, além de responsabilização legal por descumprimento normativo. A permanência da condição mantém o equipamento apto a operar com a zona de perigo acessível até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interditar o equipamento e instalar/recompor as proteções fixas e móveis previstas, dimensionadas conforme o manual do fabricante; (ii) restabelecer e testar os intertravamentos, garantindo a parada segura ao abrir a proteção e a impossibilidade de operação com ela removida; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste funcional documentado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o botão de emergência estiver inoperante, inacessível ou inexistente em máquina cuja parada de emergência seja indispensável para interromper movimento perigoso.',
  texto_fundamentacao_normativa = 'O dispositivo de parada de emergência deve estar disponível, funcional, de fácil acesso e claramente sinalizado, permitindo a interrupção imediata da operação em situação de risco, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos). O critério "Testado, acessível e sinalizado" compõe o plano de inspeção da obra e constitui requisito verificável de aceitação, devendo o acionamento ser prontamente localizável pelo operador e provocar a parada segura do equipamento.',
  texto_risco_consequencia = 'Botão de emergência inoperante ou de difícil acesso impede a interrupção imediata do movimento perigoso diante de um incidente, agravando lesões e podendo transformar um quase-acidente em acidente grave ou fatal. A permanência da condição mantém o equipamento sem meio confiável de parada emergencial até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) testar o acionamento do botão de emergência de cada posto de operação, confirmando a parada segura do equipamento; (ii) reparar ou substituir o dispositivo inoperante e reposicioná-lo/sinalizá-lo de modo a ficar acessível e visível ao operador; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste funcional documentado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de chave geral ou de dispositivo de bloqueio impossibilitar a manutenção com energia isolada, ou houver histórico de intervenção com a máquina energizada.',
  texto_fundamentacao_normativa = 'A existência de chave geral e de dispositivo que permita o bloqueio e a sinalização das fontes de energia para manutenção (procedimento de bloqueio e etiquetagem) é requisito de segurança para intervenções, disciplinado pela NR-12 (Segurança no Trabalho em Máquinas e Equipamentos). O critério "Permite bloqueio para manutenção" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, assegurando a impossibilidade de reenergização acidental durante os serviços de manutenção, limpeza ou ajuste.',
  texto_risco_consequencia = 'A ausência de chave geral ou de dispositivo de bloqueio permite a reenergização ou o acionamento inadvertido da máquina durante a manutenção, expondo o mantenedor a partida inesperada, choque elétrico ou contato com partes móveis, com risco de lesão grave ou fatal. A permanência da condição mantém a manutenção sem isolamento seguro de energia até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar/adequar a chave geral e o dispositivo de bloqueio (cadeado, garra e cartão de identificação) capaz de travar a fonte de energia na posição desligada; (ii) implantar e treinar o procedimento de bloqueio e etiquetagem para toda intervenção de manutenção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o procedimento documentado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de placa de capacidade ou de advertências puder induzir sobrecarga, uso indevido ou exposição a risco não sinalizado.',
  texto_fundamentacao_normativa = 'As máquinas devem possuir placa de identificação e dados, sinais de advertência e indicação de capacidade/limites operacionais afixados de forma legível e durável, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos) e as especificações do fabricante. O critério "Placas de dados, advertências e capacidade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, permitindo a rastreabilidade do equipamento e a comunicação dos riscos e limites ao operador.',
  texto_risco_consequencia = 'A ausência ou ilegibilidade das etiquetas de dados, advertências e capacidade dificulta a identificação do equipamento e a percepção de seus limites e riscos, favorecendo sobrecarga, uso indevido e exposição a perigos não sinalizados. A permanência da condição mantém o equipamento sem comunicação visual dos riscos e limites até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as placas e sinalizações exigidas para o equipamento a partir do manual do fabricante; (ii) confeccionar e afixar, de forma legível e durável, placa de dados, advertências de risco e indicação de capacidade/limites nos pontos pertinentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a manutenção preventiva estiver vencida em item de segurança (freios, cabos, sistemas de comando) ou não houver histórico que comprove as intervenções.',
  texto_fundamentacao_normativa = 'A manutenção deve ser realizada conforme as instruções do fabricante e registrada, mantendo-se preventivas em dia e histórico disponível das intervenções, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos). O critério "Preventivas em dia, histórico disponível" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, permitindo demonstrar que os componentes de segurança e desempenho do equipamento são mantidos em condições adequadas de uso.',
  texto_risco_consequencia = 'A manutenção preventiva vencida ou sem registro impede assegurar a integridade dos componentes de segurança, elevando a probabilidade de falha mecânica, hidráulica ou elétrica em serviço, com risco de acidente e de parada não programada do equipamento. A permanência da condição mantém a rastreabilidade da manutenção comprometida até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) resgatar/estruturar o plano de manutenção conforme o manual do fabricante e executar as preventivas vencidas; (ii) organizar o histórico (fichas/ordens de serviço) com datas, itens verificados e responsável técnico; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia dos registros atualizados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o vazamento atingir superfícies de circulação (risco de escorregamento), fontes de calor/ignição ou o solo/curso d''água (risco ambiental), ou comprometer sistema de freio/hidráulico.',
  texto_fundamentacao_normativa = 'A ausência de vazamentos de óleo, combustível e fluido hidráulico é condição de integridade operacional e de segurança do equipamento, verificável por inspeção visual conforme o manual do fabricante e as boas práticas de manutenção; a estanqueidade dos sistemas evita perda de função e contaminação. O critério "Óleo, combustível, hidráulico" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, indicando que os circuitos do equipamento operam sem perda de fluidos.',
  texto_risco_consequencia = 'Vazamentos de óleo, combustível ou fluido hidráulico podem provocar pisos escorregadios, risco de incêndio na presença de fontes de ignição, contaminação de solo e água e perda de pressão em sistemas hidráulicos e de freio, comprometendo o controle do equipamento. A permanência da condição mantém ativa a fuga de fluidos e a contaminação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) localizar a origem do vazamento e reparar/substituir vedações, mangueiras ou conexões conforme o manual do fabricante; (ii) conter e remover o fluido derramado com material absorvente e destinar adequadamente o resíduo, higienizando a área; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do reparo e da área limpa, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o operador atuar sem capacitação em equipamento de alto risco (guindaste, escavadeira, prensa, plataforma) ou com capacitação vencida.',
  texto_fundamentacao_normativa = 'A operação de máquinas e equipamentos deve ser realizada por trabalhador capacitado, com treinamento específico para o equipamento e comprovação documental, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos), cuja capacitação abrange riscos, dispositivos de segurança e procedimentos de operação. O critério "Capacitação NR-12 específica do equipamento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, exigindo evidência de habilitação/capacitação válida do operador.',
  texto_risco_consequencia = 'A operação por trabalhador não capacitado ou com treinamento vencido eleva a probabilidade de manobra incorreta, uso indevido dos dispositivos de segurança e acidentes com a própria máquina e com terceiros, além de configurar descumprimento normativo. A permanência da condição mantém o equipamento sob operação sem qualificação comprovada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar da função o operador sem capacitação válida e verificar a documentação de treinamento de toda a equipe de operação; (ii) providenciar a capacitação específica do equipamento nos termos da NR-12, com carga horária e conteúdo pertinentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia dos certificados/registros de capacitação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor quando a indisponibilidade do manual impedir a execução correta de operação ou manutenção, ou quando o manual não estiver em português.',
  texto_fundamentacao_normativa = 'O manual de instruções do fabricante, em língua portuguesa, deve estar disponível e acessível aos responsáveis pela operação e manutenção, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos), por conter os procedimentos seguros, os limites e os requisitos de manutenção do equipamento. O critério "Em português, acessível à operação/manutenção" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, garantindo o acesso à informação técnica que orienta o uso seguro.',
  texto_risco_consequencia = 'A indisponibilidade do manual em português priva operadores e mantenedores das instruções de uso seguro, limites e procedimentos de manutenção, aumentando a chance de operação incorreta e de intervenções inadequadas no equipamento. A permanência da condição mantém a operação sem a referência técnica do fabricante até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) obter junto ao fabricante/fornecedor o manual de instruções em português; (ii) disponibilizá-lo, físico ou digital, em local acessível aos responsáveis pela operação e manutenção e divulgar sua localização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do manual disponível no ponto de uso, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver circulação de terceiros na zona de perigo (raio de giro, área de projeção de cargas ou de partes móveis) sem delimitação eficaz.',
  texto_fundamentacao_normativa = 'A área de operação da máquina deve ser delimitada e sinalizada, mantendo terceiros afastados da zona de perigo durante o funcionamento, conforme a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos) e o plano de sinalização do canteiro. O critério "Delimitação, afastamento de terceiros" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, assegurando barreira física e/ou sinalização que impeça o acesso não autorizado ao raio de ação do equipamento.',
  texto_risco_consequencia = 'A área de operação sem delimitação permite a aproximação de terceiros à zona de perigo, expondo-os a atropelamento, contato com o raio de giro, projeção de materiais ou queda de cargas, com risco de lesão grave ou fatal. A permanência da condição mantém a zona de perigo acessível a pessoas não autorizadas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) delimitar e isolar a área de operação com barreiras físicas e sinalização, dimensionadas ao raio de ação do equipamento; (ii) definir e comunicar o controle de acesso, mantendo afastados os trabalhadores não envolvidos na operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da área isolada e sinalizada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando máquinas em uso no canteiro não constarem do inventário do PGR, impedindo a análise de risco e a definição de medidas de controle.',
  texto_fundamentacao_normativa = 'As máquinas e equipamentos presentes no canteiro devem estar identificados e considerados no inventário de riscos do Programa de Gerenciamento de Riscos (PGR), de modo a subsidiar a avaliação de riscos e as medidas de controle, conforme a NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais), articulada à NR-12. O critério "Máquinas do canteiro identificadas no PGR" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, exigindo inventário atualizado e coerente com os equipamentos efetivamente em uso.',
  texto_risco_consequencia = 'O inventário de máquinas desatualizado deixa equipamentos fora da avaliação de riscos do PGR, com medidas de controle não previstas para os perigos reais do canteiro, fragilizando a gestão de segurança e a defesa em eventual fiscalização. A permanência da condição mantém máquinas em operação sem cobertura no gerenciamento de riscos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar levantamento das máquinas efetivamente presentes no canteiro e confrontar com o inventário do PGR; (ii) atualizar o inventário e o inventário de riscos, incluindo os equipamentos ausentes e revisando as medidas de controle; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia do PGR atualizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-05' and item_numero = 10;

-- ST-06 (21 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o entulho obstruir rotas de fuga, acessos de emergência ou criar risco iminente de queda/tropeçamento em áreas de grande circulação de pessoal.',
  texto_fundamentacao_normativa = 'A ordem e a limpeza do canteiro são requisito permanente de segurança: frentes de serviço e áreas comuns devem permanecer livres de entulho e obstruções, com remoção sistemática dos resíduos gerados. Aplica-se a NR-18 (Segurança e Saúde no Trabalho na Indústria da Construção), que exige a manutenção da organização, da limpeza e da desobstrução das áreas de trabalho e de circulação. O critério "Frentes e áreas comuns sem entulho/obstruções" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições do canteiro.',
  texto_risco_consequencia = 'O acúmulo de entulho e a obstrução das áreas comuns geram tropeçamentos, quedas de mesmo nível, dificuldade de evacuação em emergência, além de favorecer princípios de incêndio e a proliferação de vetores. A permanência da condição mantém ativo o risco de acidente por circulação insegura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remover imediatamente o entulho e as obstruções das frentes e áreas comuns, destinando os resíduos aos coletores adequados; (ii) implantar rotina periódica de limpeza e ordenamento (housekeeping), com responsável designado por frente; (iii) evidenciar a área desobstruída e limpa com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica onde houver tráfego de máquinas pesadas ou veículos compartilhando via com pedestres sem segregação física.',
  texto_fundamentacao_normativa = 'As vias de circulação do canteiro devem ser definidas, sinalizadas e dimensionadas, com segregação entre o fluxo de pessoas e o de máquinas/veículos. Aplica-se a NR-18 (circulação e vias de acesso do canteiro), que exige a definição das vias e a separação dos fluxos, complementada pelo projeto de layout/logística do canteiro e pelas boas práticas de controle da interface homem-máquina. O critério "Vias definidas, segregação homem × máquina" integra o plano de inspeção e constitui requisito verificável de aceitação das condições de acesso e circulação.',
  texto_risco_consequencia = 'A ausência de vias definidas e de segregação homem × máquina expõe o trabalhador a atropelamento, prensagem e colisão, sobretudo em pontos de manobra, carga e descarga. A permanência da condição mantém ativo o risco de acidente grave ou fatal por conflito de fluxos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir e demarcar fisicamente as vias de pedestres e de veículos/máquinas (barreiras, faixas, cones e passagens exclusivas); (ii) sinalizar sentidos, travessias e pontos de manobra, disciplinando velocidade e uso de sinaleiro nas áreas de conflito; (iii) evidenciar a segregação implantada com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em frentes com operação noturna, escavações, trabalho em altura ou tarefas de precisão em que a baixa iluminância eleve o risco de acidente.',
  texto_fundamentacao_normativa = 'As áreas de trabalho e de circulação devem dispor de iluminação adequada, natural ou artificial, incluindo o período noturno, de modo a permitir a execução segura das tarefas e o deslocamento seguro do pessoal. Aplica-se a NR-18, que exige iluminação suficiente nas frentes e vias do canteiro. Os níveis de iluminância devem observar o projeto/especificação e as boas práticas para cada tipo de tarefa e via. O critério "Áreas de trabalho e circulação, incluindo noturno" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A iluminação insuficiente dificulta a percepção de obstáculos, desníveis e partes móveis, aumentando a probabilidade de quedas, choques, erros operacionais e fadiga visual, com agravamento no trabalho noturno. A permanência da condição mantém ativo o risco de acidente por baixa visibilidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reforçar a iluminação das áreas de trabalho e circulação identificadas como deficientes, dimensionando pontos de luz conforme a tarefa e a via; (ii) prever iluminação de circulação e de emergência para as operações noturnas, com manutenção das luminárias; (iii) evidenciar as áreas iluminadas, se possível com medição de iluminância, por registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a sinalização faltante for de emergência (rota de fuga, extintor, ponto de encontro) ou de advertência sobre risco grave.',
  texto_fundamentacao_normativa = 'O canteiro deve dispor de sinalização de segurança que identifique obrigações (uso de EPI), advertências de risco e recursos de emergência, com cores e símbolos padronizados. Aplicam-se a NR-26 (sinalização de segurança, cores e símbolos) e a NR-18 (sinalização de segurança no canteiro de obras). O critério "Placas de obrigação, advertência e emergência" integra o plano de inspeção e constitui requisito verificável de aceitação da comunicação de riscos da obra.',
  texto_risco_consequencia = 'A falta ou a inadequação da sinalização impede que trabalhadores e visitantes reconheçam obrigações, riscos e recursos de emergência, aumentando a exposição a acidentes e retardando a resposta a incidentes. A permanência da condição mantém ativa a deficiência de comunicação de riscos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar as placas de obrigação, advertência e emergência faltantes, em cores e símbolos padronizados e em pontos visíveis; (ii) revisar o plano de sinalização do canteiro, priorizando acessos, frentes de risco e recursos de emergência; (iii) evidenciar a sinalização implantada com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — proteção coletiva contra quedas é medida de prioridade máxima; manter Crítica sempre que houver aberturas de piso, periferias ou desníveis desprotegidos com risco de queda de pessoas ou materiais.',
  texto_fundamentacao_normativa = 'As proteções coletivas — guarda-corpo, rodapé e fechamento de aberturas de piso — devem estar instaladas e íntegras em periferias, vãos e desníveis, prevalecendo sobre a proteção individual. Aplicam-se a NR-18 (guarda-corpo, rodapé e proteção de aberturas no piso) e a NR-35 (trabalho em altura e proteção contra quedas). O critério "Guarda-corpo, rodapé, fechamento de aberturas de piso" integra o plano de inspeção e constitui requisito verificável de aceitação das medidas de proteção coletiva.',
  texto_risco_consequencia = 'A ausência ou fragilidade de guarda-corpo, rodapé e fechamento de aberturas expõe os trabalhadores à queda de altura e a terceiros à queda de materiais, com potencial de lesão grave ou morte. A permanência da condição mantém ativo o risco de queda em pontos desprotegidos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) isolar de imediato as áreas com aberturas e periferias desprotegidas, restringindo o acesso; (ii) instalar/recompor guarda-corpo, rodapé e fechamento de aberturas de piso conforme especificação, verificando resistência e fixação; (iii) evidenciar as proteções coletivas instaladas com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falha no tapume/portão permitir acesso de terceiros não autorizados a áreas de risco ou expor a via pública a queda de materiais.',
  texto_fundamentacao_normativa = 'A obra deve ser delimitada por tapumes íntegros e fechamento adequado, com portões controlados, isolando o canteiro das áreas públicas e vizinhas. Aplica-se a NR-18 (tapumes e fechamento do canteiro de obras), que exige a delimitação da obra e o controle de acesso. O critério "Íntegros, com portões controlados" integra o plano de inspeção e constitui requisito verificável de aceitação do fechamento perimetral.',
  texto_risco_consequencia = 'Tapumes danificados ou portões sem controle permitem o ingresso de pessoas não autorizadas em áreas de risco, furto de materiais e a exposição da via pública a projeção/queda de detritos, ampliando a responsabilidade da obra por acidentes com terceiros. A permanência da condição mantém ativo o risco de acesso indevido e de dano a terceiros até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reparar ou substituir os trechos de tapume danificados, restabelecendo a integridade do fechamento perimetral; (ii) restabelecer o controle de acesso nos portões (fechaduras, cancela, guarda ou registro de entrada); (iii) evidenciar o tapume íntegro e o portão controlado com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a escada de mão danificada ou mal apoiada estiver em uso para acesso a altura elevada ou como único meio de acesso a pavimento.',
  texto_fundamentacao_normativa = 'As escadas de mão devem estar íntegras, apoiadas e amarradas, ultrapassando em cerca de 1 metro o ponto de apoio superior quando usadas para acesso a nível diferente, e utilizadas conforme a boa técnica. Aplicam-se a NR-18 (escadas de mão: integridade, fixação e a ultrapassagem do piso superior) e a NR-35 quando o acesso configurar trabalho em altura. O critério "Íntegras, amarradas, ultrapassando 1 m do apoio" integra o plano de inspeção e constitui requisito verificável de aceitação do uso de escadas de mão.',
  texto_risco_consequencia = 'Escadas danificadas, sem amarração ou sem a ultrapassagem do apoio superior favorecem o escorregamento, o tombamento e a queda do trabalhador durante o acesso, com risco de lesão grave. A permanência da condição mantém ativo o risco de queda no uso de escadas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso as escadas danificadas e substituí-las por unidades íntegras; (ii) assegurar amarração/fixação, apoio estável e a ultrapassagem de aproximadamente 1 m do piso superior, orientando o uso correto; (iii) evidenciar a escada conforme e corretamente instalada com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — andaime é meio de trabalho em altura de alto risco; manter Crítica sempre que houver falta de projeto/ART, piso incompleto, rodízios não travados ou acesso inseguro.',
  texto_fundamentacao_normativa = 'Os andaimes devem ser montados conforme projeto e ART do profissional habilitado, com piso completo e travado, rodízios travados (nos andaimes móveis), guarda-corpo/rodapé e acesso interno seguro. Aplicam-se a NR-18 (montagem, dimensionamento e uso de andaimes) e a NR-35 (trabalho em altura). O critério "Projeto/ART, pisos completos, rodízios travados, acesso seguro" integra o plano de inspeção e constitui requisito verificável de aceitação dos andaimes.',
  texto_risco_consequencia = 'Andaimes sem projeto/ART, com piso incompleto, rodízios destravados ou acesso improvisado podem colapsar, deslocar-se ou provocar queda de pessoas e materiais de altura, com potencial de acidente grave ou fatal. A permanência da condição mantém ativo o risco estrutural e de queda no uso do andaime até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interditar o andaime não conforme, impedindo o uso até a regularização; (ii) providenciar/validar o projeto e a ART, completar e travar o piso, travar os rodízios, instalar guarda-corpo/rodapé e prever acesso interno seguro; (iii) evidenciar o andaime conforme e a documentação com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a passarela/rampa vencer altura elevada, apresentar guarda-corpo ausente/frágil ou piso escorregadio em fluxo intenso.',
  texto_fundamentacao_normativa = 'Passarelas e rampas devem ser dimensionadas para as cargas e o fluxo previstos, dotadas de guarda-corpo e rodapé e com piso antiderrapante, garantindo travessia e deslocamento seguros. Aplica-se a NR-18 (passarelas, rampas e proteção de bordas), complementada pelo dimensionamento de projeto e boas práticas de circulação. O critério "Dimensionadas, com guarda-corpo e antiderrapante" integra o plano de inspeção e constitui requisito verificável de aceitação das travessias e rampas.',
  texto_risco_consequencia = 'Passarelas e rampas subdimensionadas, sem guarda-corpo ou sem superfície antiderrapante favorecem quedas de altura, quedas de mesmo nível por escorregamento e colapso por sobrecarga, atingindo trabalhadores em trânsito. A permanência da condição mantém ativo o risco de queda na travessia até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o dimensionamento da passarela/rampa frente à carga e ao fluxo, reforçando a estrutura quando necessário; (ii) instalar guarda-corpo e rodapé e aplicar superfície antiderrapante, limitando a inclinação das rampas; (iii) evidenciar a passarela/rampa conforme com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver ausência de instalações sanitárias, quantidade muito inferior ao efetivo ou condições de higiene com risco sanitário.',
  texto_fundamentacao_normativa = 'As instalações sanitárias devem existir em quantidade proporcional ao efetivo, manter-se limpas e higienizadas e dispor de papel higiênico e sabão. Aplicam-se a NR-24 (condições sanitárias e de conforto nos locais de trabalho) e a NR-18 (áreas de vivência), que estabelecem a proporção por trabalhador e as condições de higiene. O critério "Quantidade por efetivo, limpeza, papel/sabão" integra o plano de inspeção e constitui requisito verificável de aceitação das instalações sanitárias.',
  texto_risco_consequencia = 'Instalações sanitárias insuficientes ou mal higienizadas favorecem a transmissão de doenças, comprometem a dignidade e a higiene do trabalhador e podem gerar autuações e paralisações. A permanência da condição mantém ativo o risco sanitário e de adoecimento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) adequar a quantidade de bacias, mictórios e lavatórios à proporção do efetivo da obra; (ii) implantar rotina de limpeza e reposição contínua de papel higiênico e sabão; (iii) evidenciar as instalações sanitárias limpas e abastecidas com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando não houver armários individuais para guarda de pertences/roupas ou quando a ventilação for insuficiente ao efetivo.',
  texto_fundamentacao_normativa = 'O vestiário deve dispor de armários individuais para guarda de roupas e pertences e de ventilação adequada, oferecendo condições dignas de troca de vestimenta. Aplicam-se a NR-24 (vestiários: armários individuais e ventilação) e a NR-18 (áreas de vivência). O critério "Armários individuais, ventilação" integra o plano de inspeção e constitui requisito verificável de aceitação do vestiário.',
  texto_risco_consequencia = 'A ausência de armários individuais e a ventilação deficiente comprometem a higiene, favorecem a contaminação cruzada de roupas e a proliferação de fungos e odores, além de reduzir o conforto do trabalhador. A permanência da condição mantém ativa a inadequação da área de vivência até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) disponibilizar armários individuais em número compatível com o efetivo, separando roupas de trabalho e pessoais; (ii) melhorar a ventilação do ambiente (aberturas/exaustão) e a limpeza periódica; (iii) evidenciar o vestiário adequado com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 11;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de proteção contra intempéries ou de lavatório expuser as refeições à contaminação e a área a risco sanitário.',
  texto_fundamentacao_normativa = 'O refeitório deve dispor de mesas e assentos em número compatível com o efetivo, lavatório para higienização e cobertura/proteção contra intempéries, garantindo a realização das refeições em condições de higiene e conforto. Aplicam-se a NR-24 (refeitório) e a NR-18 (áreas de vivência). O critério "Mesas, assentos, lavatório, proteção contra intempéries" integra o plano de inspeção e constitui requisito verificável de aceitação do refeitório.',
  texto_risco_consequencia = 'Refeitório sem assentos suficientes, sem lavatório ou desprotegido de intempéries favorece a contaminação dos alimentos, as doenças de veiculação alimentar e a realização de refeições em locais impróprios, comprometendo a saúde do efetivo. A permanência da condição mantém ativo o risco sanitário no momento das refeições até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) prover mesas, assentos e lavatório em quantidade compatível com o efetivo por turno; (ii) assegurar cobertura e fechamento que protejam contra sol, chuva e poeira, com limpeza periódica; (iii) evidenciar o refeitório conforme com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 12;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em frentes sob calor intenso ou esforço elevado, ou quando não houver qualquer ponto de água potável acessível ao trabalhador.',
  texto_fundamentacao_normativa = 'Deve ser garantida água potável, fresca e filtrada, em quantidade suficiente e em todas as frentes de trabalho. Aplicam-se a NR-24 (fornecimento de água potável nos locais de trabalho) e a NR-18 (áreas de vivência), que exigem a disponibilização de água potável ao efetivo em condições adequadas de higiene. A proporção de referência de um bebedouro para cada grupo de 25 trabalhadores adotada aqui decorre do plano de inspeção da obra e das boas práticas de dimensionamento, e não de número fixado nas normas citadas. O critério "Fresca, filtrada, em todas as frentes (1 bebedouro/25 trab.)" integra o plano de inspeção e constitui requisito verificável de aceitação do fornecimento de água potável.',
  texto_risco_consequencia = 'A indisponibilidade de água potável fresca e em quantidade suficiente favorece a desidratação, o estresse térmico e o consumo de água imprópria, com risco de mal súbito e adoecimento, sobretudo em atividades a céu aberto. A permanência da condição mantém ativo o risco à saúde por falta de hidratação segura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar bebedouros de água fresca e filtrada em todas as frentes, observando a proporção de referência do critério de inspeção de um para cada 25 trabalhadores; (ii) implantar rotina de higienização dos bebedouros e troca de filtros, com controle de potabilidade; (iii) evidenciar os pontos de água potável em operação com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 13;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando prateleiras instáveis/sobrecarregadas ou a falta de identificação criarem risco de queda de materiais sobre pessoas ou de entrega de item errado a serviço crítico.',
  texto_fundamentacao_normativa = 'O almoxarifado deve manter prateleiras estáveis e dimensionadas para a carga, com itens identificados e organizados, permitindo o armazenamento e a retirada seguros. A exigência decorre das boas práticas de armazenagem e organização e da NR-18 quanto à ordem e segurança das áreas de apoio, sendo o dimensionamento das prateleiras condicionado à carga prevista. O critério "Prateleiras seguras, itens identificados" integra o plano de inspeção e constitui requisito verificável de aceitação do almoxarifado.',
  texto_risco_consequencia = 'Prateleiras instáveis ou sobrecarregadas e a falta de identificação favorecem a queda de materiais sobre o almoxarife, erros de separação e a entrega de itens inadequados a serviços de segurança, além de dificultar o controle de estoque. A permanência da condição mantém ativo o risco de queda de materiais e de erro de fornecimento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a estabilidade e a ancoragem das prateleiras, redistribuindo cargas e respeitando a capacidade de cada nível; (ii) identificar e organizar os itens por tipo, com etiquetagem e endereçamento; (iii) evidenciar o almoxarifado organizado e seguro com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 14;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o empilhamento instável ou a proximidade de redes elétricas energizadas criar risco iminente de desabamento da pilha ou de contato/arco elétrico.',
  texto_fundamentacao_normativa = 'O armazenamento de materiais deve garantir empilhamento estável, com altura e amarração compatíveis com o material, e respeitar distância de segurança em relação a redes elétricas. Aplicam-se a NR-18 e às boas práticas de armazenagem quanto à estabilidade das pilhas, e a NR-10 (segurança em instalações e serviços em eletricidade) quanto ao afastamento de partes energizadas. O critério "Empilhamento estável, distância de redes elétricas" integra o plano de inspeção e constitui requisito verificável de aceitação do armazenamento.',
  texto_risco_consequencia = 'O empilhamento instável pode desabar sobre trabalhadores e equipamentos, enquanto a proximidade de materiais e da movimentação junto a redes elétricas expõe ao risco de choque e arco elétrico. A permanência da condição mantém ativos os riscos de soterramento/esmagamento e de contato elétrico até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer o empilhamento em bases niveladas, limitando altura e travando as pilhas conforme o material; (ii) reposicionar o armazenamento e a movimentação para respeitar a distância de segurança das redes elétricas, isolando/sinalizando a área; (iii) evidenciar o armazenamento estável e afastado das redes com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 15;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — inflamáveis e gases sob risco de incêndio/explosão exigem tratamento prioritário; manter Crítica sempre que houver cilindros soltos, mistura de gases incompatíveis ou área sem ventilação.',
  texto_fundamentacao_normativa = 'Líquidos inflamáveis e gases devem ser armazenados em área ventilada e segregada, com cilindros presos (posição vertical, correntados) e separados por tipo/compatibilidade, afastados de fontes de ignição. Aplicam-se a NR-20 (segurança com inflamáveis e combustíveis) e a NR-18, complementadas pelas boas práticas de manuseio e estocagem de gases. O critério "Área ventilada, cilindros presos e separados por tipo" integra o plano de inspeção e constitui requisito verificável de aceitação do armazenamento de inflamáveis e gases.',
  texto_risco_consequencia = 'O armazenamento inadequado de inflamáveis e gases, com cilindros soltos, gases incompatíveis próximos ou ambiente sem ventilação, favorece vazamentos, incêndio e explosão, com potencial de vítimas múltiplas e destruição do canteiro. A permanência da condição mantém ativo o risco de incêndio/explosão até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) transferir os inflamáveis e cilindros para área ventilada, segregada e afastada de fontes de ignição, sinalizando a proibição de fogo; (ii) fixar os cilindros na vertical (correntes/suportes), separando-os por tipo e compatibilidade e mantendo capacetes de proteção nas válvulas; (iii) evidenciar o armazenamento conforme com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 16;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando produto de alta periculosidade estiver sem FISPQ/identificação e sem contenção, com risco de exposição química ou de contaminação do solo/água.',
  texto_fundamentacao_normativa = 'Os produtos químicos devem estar identificados/rotulados, dispor da respectiva FISPQ (Ficha de Informações de Segurança de Produtos Químicos) no local de uso/armazenamento e contar com contenção adequada. Aplicam-se a NR-26 (rotulagem preventiva e informação sobre produtos químicos) e a norma técnica de FISPQ ABNT NBR 14725, que define a ficha de segurança segundo o GHS. O critério "Identificação, contenção e FISPQ no local" integra o plano de inspeção e constitui requisito verificável de aceitação da gestão de produtos químicos.',
  texto_risco_consequencia = 'A falta de identificação, de FISPQ acessível e de contenção impede a manipulação segura e a resposta correta a incidentes, expondo o trabalhador à intoxicação/queimadura e o ambiente à contaminação por vazamentos. A permanência da condição mantém ativo o risco químico e ambiental até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) rotular e identificar todos os produtos químicos e disponibilizar a FISPQ correspondente no local de uso/armazenamento; (ii) implantar bacias/dispositivos de contenção e ordenar a estocagem por compatibilidade química; (iii) evidenciar a identificação, a contenção e a presença das FISPQ com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 17;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de segregação misturar resíduos perigosos com comuns ou gerar acúmulo com risco sanitário, de incêndio ou de passivo ambiental.',
  texto_fundamentacao_normativa = 'Os resíduos gerados no canteiro devem ser segregados na origem em baias/coletores identificados, conforme sua classe, permitindo destinação adequada. Aplicam-se a Resolução CONAMA nº 307 (gestão dos resíduos da construção civil) e as boas práticas de gerenciamento de resíduos, com apoio na classificação de resíduos sólidos. O critério "Baias/coletores identificados" integra o plano de inspeção e constitui requisito verificável de aceitação da gestão de resíduos do canteiro.',
  texto_risco_consequencia = 'A falta de baias/coletores identificados leva à mistura de resíduos comuns e perigosos, ao acúmulo desordenado e à destinação irregular, gerando risco sanitário, de incêndio, atração de vetores e passivo ambiental com sanções. A permanência da condição mantém ativo o risco ambiental e sanitário por gestão inadequada de resíduos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar baias/coletores identificados por classe de resíduo (inertes, recicláveis, perigosos e rejeitos); (ii) definir rotina de coleta, segregação e destinação a receptores licenciados, com registro de destinação; (iii) evidenciar as baias/coletores identificados e em uso com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 18;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — risco elétrico com potencial de choque fatal; manter Crítica sempre que houver cabos com emendas precárias, isolamento comprometido ou circuitos sem dispositivo diferencial-residual (DR).',
  texto_fundamentacao_normativa = 'As ferramentas elétricas e a instalação provisória do canteiro devem apresentar cabos íntegros, sem emendas precárias e com isolamento adequado, e os circuitos devem contar com dispositivo diferencial-residual (DR) e aterramento. Aplicam-se a NR-10 (segurança em instalações e serviços em eletricidade, incluindo proteção por DR) e a NR-18 (instalações elétricas provisórias do canteiro). O critério "Cabos sem emendas precárias, DR nos circuitos" integra o plano de inspeção e constitui requisito verificável de aceitação das instalações e ferramentas elétricas.',
  texto_risco_consequencia = 'Cabos com emendas precárias e circuitos sem DR expõem o trabalhador a choque elétrico, queimaduras e eletrocussão, além de favorecerem curtos-circuitos e princípios de incêndio. A permanência da condição mantém ativo o risco elétrico grave até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir cabos danificados e eliminar emendas precárias, restabelecendo o isolamento e os conectores adequados; (ii) instalar/verificar o dispositivo diferencial-residual (DR) e o aterramento nos circuitos e nas ferramentas, testando o funcionamento; (iii) evidenciar as instalações e ferramentas conformes com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 19;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando faltarem extintores em área de risco de incêndio, houver carga vencida/obstruída ou inexistir kit de primeiros socorros acessível.',
  texto_fundamentacao_normativa = 'Os extintores devem estar distribuídos conforme o risco, sinalizados, desobstruídos e com carga válida, e o canteiro deve dispor de material de primeiros socorros acessível. Aplicam-se a NR-23 (proteção contra incêndios e uso de extintores) e a NR-18, complementadas pela norma técnica de extintores de incêndio e pelas boas práticas de atendimento de emergência. O critério "Distribuídos, sinalizados, carga válida, kit disponível" integra o plano de inspeção e constitui requisito verificável de aceitação dos recursos de combate a incêndio e primeiros socorros.',
  texto_risco_consequencia = 'A falta, a obstrução ou a inaptidão dos extintores compromete a resposta imediata a princípios de incêndio, e a ausência de kit de primeiros socorros retarda o atendimento a acidentados, agravando lesões e a evolução do sinistro. A permanência da condição mantém ativa a deficiência de resposta a emergências até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) distribuir extintores compatíveis com a classe de risco de cada área, mantendo-os sinalizados, desobstruídos e com carga válida; (ii) prover e reabastecer o kit de primeiros socorros em local acessível e sinalizado, com pessoal orientado; (iii) evidenciar os extintores e o kit disponíveis e conformes com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 20;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a integridade das rotas de fuga é condição de sobrevivência em emergência; manter Crítica sempre que rotas estiverem obstruídas, não sinalizadas ou sem mapa de emergência divulgado.',
  texto_fundamentacao_normativa = 'As rotas de fuga devem permanecer desobstruídas e sinalizadas, e o canteiro deve dispor de mapa/plano de emergência que oriente a evacuação e o ponto de encontro. Aplicam-se a NR-23 (saídas e rotas para situações de emergência) e a NR-18, complementadas pelo plano de atendimento a emergências e pelas boas práticas de sinalização de abandono. O critério "Desobstruídas e sinalizadas" integra o plano de inspeção e constitui requisito verificável de aceitação das rotas de fuga e do mapa de emergência.',
  texto_risco_consequencia = 'Rotas de fuga obstruídas ou sem sinalização e a falta de mapa de emergência retardam ou impedem a evacuação em incêndio ou outro sinistro, elevando o risco de vítimas por confinamento e pânico. A permanência da condição mantém ativa a incapacidade de evacuação segura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) desobstruir imediatamente as rotas de fuga e mantê-las permanentemente livres; (ii) sinalizar as rotas e saídas de emergência e divulgar o mapa de emergência com pontos de encontro, orientando o efetivo; (iii) evidenciar as rotas desobstruídas, a sinalização e o mapa afixado com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-06' and item_numero = 21;

-- ST-07 (11 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter esta classificação sempre que houver entrantes no espaço confinado sem PET válida; regularizar somente após suspensão imediata da entrada e emissão da permissão.',
  texto_fundamentacao_normativa = 'A entrada em espaço confinado é condicionada à emissão prévia de Permissão de Entrada e Trabalho (PET) específica para a tarefa e válida apenas para o turno, documento que consolida a análise de riscos, as medidas de controle, a liberação da atmosfera e as autorizações de supervisor, vigia e entrantes. Aplica-se a NR-33 (Segurança e Saúde nos Trabalhos em Espaços Confinados), que torna a PET requisito obrigatório e intransferível, integrando-se ao PGR previsto na NR-01. O critério ''permissão específica, válida só para o turno'' constitui requisito verificável de aceitação da liberação do serviço.',
  texto_risco_consequencia = 'A execução de trabalhos sem PET válida suprime a barreira documental que assegura a análise de riscos, a liberação atmosférica e a definição de responsáveis, expondo os entrantes a atmosferas IPVS (deficiência/enriquecimento de oxigênio, inflamabilidade e toxicidade) e a resgate desassistido, com potencial de acidente fatal. A permanência da condição mantém a entrada irregular e o risco ativo até a emissão da permissão. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender imediatamente qualquer entrada e retirar os entrantes até a regularização; (ii) emitir a PET específica do turno, com análise de riscos, liberação atmosférica registrada e assinaturas de supervisor de entrada, vigia e entrantes; (iii) evidenciar a PET emitida e afixada no acesso ao espaço com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica caso existam entrantes no espaço confinado sem supervisor de entrada designado e presente para autorizar e encerrar a operação.',
  texto_fundamentacao_normativa = 'O supervisor de entrada é o responsável formalmente designado por autorizar, acompanhar e encerrar a entrada, verificando o cumprimento das medidas da PET e determinando a evacuação diante de qualquer alteração das condições de segurança. A NR-33 exige a designação formal e a capacitação específica de supervisor de entrada, com carga horária mínima de 40 horas estabelecida pela própria norma. O critério ''designado formalmente, treinado (40h)'' é requisito verificável de habilitação da função e de aceitação da liberação da tarefa.',
  texto_risco_consequencia = 'A ausência de supervisor de entrada presente e habilitado retira a autoridade técnica responsável por validar as condições da PET e ordenar a evacuação, permitindo que desvios atmosféricos ou operacionais evoluam sem intervenção, com risco de intoxicação, asfixia ou incêndio para os entrantes. A permanência da condição mantém a operação sem comando de segurança qualificado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) designar formalmente o supervisor de entrada e assegurar sua presença durante toda a operação, com registro na PET; (ii) comprovar a capacitação de 40 horas exigida e a validade do treinamento, substituindo o profissional se não habilitado; (iii) evidenciar a designação e o certificado com registro fotográfico ou documental ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter esta classificação enquanto houver entrantes sem vigia dedicado no exterior; a entrada só pode prosseguir com vigia posicionado e exclusivo.',
  texto_fundamentacao_normativa = 'O vigia é o trabalhador posicionado no exterior do espaço confinado, com a função exclusiva de monitorar os entrantes, manter comunicação contínua, controlar o acesso e acionar o resgate, não podendo acumular outras atribuições que o afastem do posto. A NR-33 estabelece a obrigatoriedade do vigia dedicado e a vedação ao exercício simultâneo de outras funções durante a entrada. O critério ''permanece no exterior, sem outras funções'' é requisito verificável de aceitação da operação.',
  texto_risco_consequencia = 'A ausência de vigia dedicado, ou o seu desvio para outras tarefas, elimina a vigilância externa e o elo de acionamento do resgate, de modo que uma emergência dentro do espaço pode não ser percebida a tempo, agravando desfechos de asfixia, intoxicação ou soterramento. A permanência da condição deixa os entrantes sem suporte externo imediato. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) posicionar vigia dedicado no exterior durante toda a permanência de entrantes, sem qualquer acúmulo de função; (ii) definir na PET o rendimento de turno e a rendição do vigia sem deixar o posto descoberto; (iii) evidenciar o vigia no posto e o registro na PET com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter esta classificação sempre que a atmosfera não estiver sendo medida antes e durante a entrada, pois a liberação atmosférica não pode ser presumida.',
  texto_fundamentacao_normativa = 'A avaliação da atmosfera é condição de liberação da entrada e deve verificar oxigênio (O2), limite inferior de explosividade (LEL) e gases tóxicos aplicáveis, como CO e H2S, antes e de forma contínua durante o trabalho, dado que as condições internas podem variar. A NR-33 exige a avaliação e o monitoramento da atmosfera do espaço confinado como requisito de entrada e permanência. O critério ''O2, LEL, CO, H2S antes e durante'' é requisito verificável de aceitação da liberação atmosférica.',
  texto_risco_consequencia = 'A falta de monitoramento contínuo impede detectar a deficiência ou o enriquecimento de oxigênio, a formação de mistura inflamável ou a elevação de gases tóxicos, expondo os entrantes a asfixia, incêndio/explosão ou intoxicação sem alarme prévio. A permanência da condição mantém a atmosfera não caracterizada e o risco não controlado ao longo da tarefa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar a medição inicial (O2, LEL, CO, H2S) antes de qualquer entrada e registrar os valores na PET; (ii) manter monitoramento contínuo durante toda a permanência, com alarmes ajustados e evacuação imediata ao disparo; (iii) evidenciar as leituras registradas e o equipamento em uso com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a atmosfera houver sido liberada com detector fora da validade de calibração ou sem bump test, invalidando as leituras que autorizaram a entrada.',
  texto_fundamentacao_normativa = 'A confiabilidade da avaliação atmosférica depende de detector de gases com calibração e teste de resposta (bump test) dentro da validade, conforme especificação do fabricante, de modo que as leituras reflitam a real concentração dos gases. A NR-33 exige que a avaliação seja feita por equipamento de medição adequado e em condições de uso; a periodicidade de bump test e calibração segue o manual do fabricante e as boas práticas de higiene ocupacional. O critério ''bump test/calibração dentro da validade'' é requisito verificável de aceitação do instrumento.',
  texto_risco_consequencia = 'Um detector descalibrado ou sem teste de resposta pode indicar atmosfera segura quando ela não está, ou falhar em alarmar, levando à liberação indevida da entrada e à exposição dos trabalhadores a atmosferas perigosas sem aviso. A permanência da condição compromete todas as leituras subsequentes e a validade da liberação atmosférica. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso o detector com calibração ou bump test vencidos e substituí-lo por equipamento em conformidade; (ii) executar bump test antes do turno e manter a calibração conforme o fabricante, registrando datas e resultados; (iii) evidenciar as etiquetas/registros de calibração e o teste de resposta com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a avaliação apontar atmosfera IPVS ou fonte contínua de contaminante e a entrada ocorrer sem ventilação/exaustão adequada.',
  texto_fundamentacao_normativa = 'A ventilação ou exaustão, dimensionada conforme a avaliação de riscos, é medida de controle destinada a estabelecer e manter atmosfera segura no espaço confinado, renovando o ar e removendo contaminantes e vapores. A NR-33 prevê a adoção de ventilação como medida de controle para tornar e manter o ambiente seguro à entrada, com insuflamento/exaustão compatíveis com a fonte de risco. O critério ''insuflamento conforme avaliação'' é requisito verificável de aceitação das medidas de controle atmosférico.',
  texto_risco_consequencia = 'A ventilação insuficiente ou inadequada permite o acúmulo ou a reposição de gases perigosos e a manutenção de atmosfera deficiente em oxigênio, anulando o efeito das demais barreiras e expondo os entrantes a asfixia, intoxicação ou incêndio. A permanência da condição mantém a atmosfera dependente apenas de EPI, sem controle de engenharia na fonte. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar e operar ventilação/exaustão dimensionada segundo a avaliação de riscos, posicionando insuflamento/captação conforme a geometria e a fonte; (ii) confirmar por medição que a atmosfera atingiu e mantém valores seguros com a ventilação em operação; (iii) evidenciar o sistema instalado em funcionamento e as leituras com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter esta classificação enquanto a entrada ocorrer sem plano e equipe de resgate com meios próprios prontos para resposta imediata.',
  texto_fundamentacao_normativa = 'A entrada em espaço confinado exige plano e equipe de resgate com meios próprios disponíveis e capazes de resposta imediata, sem depender exclusivamente do acionamento de serviços externos, cujo tempo de deslocamento é incompatível com emergências de asfixia ou intoxicação. A NR-33 estabelece a obrigatoriedade de medidas e recursos para resgate e primeiros socorros adequados às características do espaço. O critério ''meios próprios disponíveis, não depender só de acionamento externo'' é requisito verificável de aceitação da preparação para emergência.',
  texto_risco_consequencia = 'A inexistência de plano e equipe de resgate próprios faz com que, em emergência, o socorro dependa de terceiros externos com tempo de resposta longo, período em que a vítima pode sofrer dano irreversível ou óbito; ademais, induz tentativas de resgate improvisado que multiplicam as vítimas. A permanência da condição deixa a operação sem capacidade real de salvamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar plano de resgate específico para o espaço e a tarefa, com cenários e acionamento definidos na PET; (ii) disponibilizar equipe treinada e equipamentos de resgate prontos no local antes da entrada, dispensando dependência exclusiva de socorro externo; (iii) evidenciar o plano, a equipe e os equipamentos posicionados com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em entrada vertical com risco de queda, afogamento ou soterramento, quando a ausência de tripé/guincho inviabiliza a retirada rápida da vítima.',
  texto_fundamentacao_normativa = 'Em acessos verticais, o tripé com guincho e sistema de içamento acoplado ao cinturão/talabarte do entrante é o meio que permite a retirada imediata do trabalhador sem exposição de outros ao interior do espaço, sendo componente essencial do plano de resgate. A NR-33 exige recursos de resgate compatíveis com a configuração do espaço; em entradas verticais aplicam-se também as boas práticas de içamento e os requisitos de sistemas de ancoragem e retenção. O critério ''instalados quando entrada vertical'' é requisito verificável de aceitação dos meios de resgate.',
  texto_risco_consequencia = 'A falta de tripé e guincho em entrada vertical impede o resgate rápido da vítima pelo exterior, obrigando à entrada de socorristas no ambiente perigoso e prolongando o tempo até a retirada, com agravamento de intoxicação, asfixia ou afogamento. A permanência da condição deixa a rota vertical de resgate sem meio mecânico de içamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar tripé e guincho de resgate dimensionados para a carga e a geometria do acesso vertical, ancorados conforme especificação; (ii) manter o entrante conectado ao sistema de içamento durante toda a permanência, com inspeção prévia dos componentes; (iii) evidenciar o tripé/guincho montados e o entrante conectado com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se ocorrer perda de comunicação entre vigia e entrantes durante a permanência no espaço, situação que impõe evacuação imediata.',
  texto_fundamentacao_normativa = 'A comunicação contínua entre o vigia e os entrantes, por rádio ou meio equivalente adequado ao ambiente, é o canal que permite acompanhar as condições internas, transmitir ordens de evacuação e acionar o resgate sem retardo. A NR-33 exige meios de comunicação eficazes entre vigia e entrantes durante toda a entrada, compatíveis com a atmosfera (inclusive intrinsecamente seguros em ambientes com risco de explosão). O critério ''rádio/contato contínuo'' é requisito verificável de aceitação da operação.',
  texto_risco_consequencia = 'A ausência ou a interrupção da comunicação impede que o vigia perceba a necessidade de evacuação e que os entrantes solicitem auxílio, retardando a resposta a emergências atmosféricas ou de saúde e reduzindo a chance de resgate bem-sucedido. A permanência da condição isola os entrantes do suporte externo durante a tarefa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) prover meio de comunicação contínua e adequado ao ambiente (rádio intrinsecamente seguro quando houver risco de explosão) e testá-lo antes da entrada; (ii) estabelecer protocolo de comunicação periódica e sinal de evacuação, registrando-o na PET; (iii) evidenciar os equipamentos de comunicação em uso e o teste realizado com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver entrante executando a tarefa sem o treinamento de 16h ou com reciclagem vencida, hipótese que veda a sua autorização.',
  texto_fundamentacao_normativa = 'Os trabalhadores autorizados a entrar em espaços confinados devem possuir capacitação específica sobre riscos, medidas de controle, uso de equipamentos e procedimentos de emergência, com carga horária mínima de 16 horas e reciclagem periódica em dia, conforme a NR-33. A capacitação é condição de habilitação do entrante e do vigia. O critério ''reciclagem em dia'' é requisito verificável de aceitação da autorização dos trabalhadores.',
  texto_risco_consequencia = 'O emprego de trabalhadores sem o treinamento de 16h ou com reciclagem vencida coloca no espaço pessoas que podem não reconhecer os riscos, não operar corretamente os equipamentos nem reagir adequadamente à emergência, aumentando a probabilidade e a gravidade de acidentes. A permanência da condição mantém entrantes não habilitados expostos ao ambiente confinado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar da tarefa os trabalhadores sem treinamento válido de 16h ou com reciclagem vencida; (ii) providenciar a capacitação/reciclagem e vincular na PET apenas entrantes e vigias habilitados; (iii) evidenciar os certificados e a lista de autorizados atualizada com fotografia ou documento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando espaço confinado não identificado permanecer acessível, permitindo entrada inadvertida sem PET nem medidas de controle.',
  texto_fundamentacao_normativa = 'A gestão de espaços confinados exige a prévia identificação, o cadastro e a sinalização de todos os espaços da obra com o aviso ''Entrada Proibida'', de forma a impedir o acesso não autorizado e a orientar a aplicação do procedimento de entrada. A NR-33 exige a identificação e a sinalização dos espaços confinados e a adoção de medidas para impedir a entrada de pessoas não autorizadas, em articulação com o PGR da NR-01. O critério ''cadastro e sinalização Entrada Proibida'' é requisito verificável de aceitação da gestão preventiva.',
  texto_risco_consequencia = 'A falta de identificação, cadastro e sinalização permite que trabalhadores adentrem espaços confinados sem saber do risco e sem PET, avaliação atmosférica ou vigia, expondo-se a atmosferas perigosas com possibilidade de acidente fatal por entrada inadvertida. A permanência da condição mantém acessos não sinalizados e liberados ao público da obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar e cadastrar os espaços confinados da obra, classificando-os quanto aos riscos; (ii) sinalizar cada acesso com placa ''Entrada Proibida — Espaço Confinado'' e restringir fisicamente a entrada não autorizada; (iii) evidenciar o cadastro e a sinalização instalada com fotografia ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-07' and item_numero = 11;

-- ST-08 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver frente de trabalho em altura ativa sem PT emitida ou com Análise de Risco (APR) ausente, vencida ou não aderente à tarefa; reduzir a Maior apenas se a atividade estiver paralisada e isolada até a regularização.',
  texto_fundamentacao_normativa = 'O trabalho em altura só pode ser autorizado mediante Permissão de Trabalho (PT) específica, emitida e válida, precedida de Análise de Risco que identifique perigos, medidas de controle e condições impeditivas da tarefa. A exigência decorre da NR-35 (Trabalho em Altura), que condiciona a liberação da atividade à análise prévia de risco e à autorização formal, e do plano de inspeção da obra. O critério "Emitida e válida, com análise de risco" constitui requisito verificável de aceitação: sem PT válida e APR aderente à frente, a atividade não pode ser liberada.',
  texto_risco_consequencia = 'A execução de trabalho em altura sem PT válida ou sem Análise de Risco aderente suprime a barreira de planejamento e autorização, permitindo que perigos não avaliados (ausência de ancoragem, zona de queda insuficiente, condição climática adversa) resultem em queda de altura com potencial de lesão grave ou fatal. A permanência da condição mantém a frente liberada de modo irregular até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar imediatamente a frente em altura e emitir/revalidar a PT específica, garantindo prazo de validade compatível com a jornada e o escopo; (ii) elaborar ou revisar a Análise de Risco (APR) da tarefa com o supervisor e a equipe, contemplando medidas de controle e condições impeditivas; (iii) evidenciar a regularização com PT e APR assinadas e registro fotográfico da frente já autorizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando a linha de vida for o sistema primário de proteção contra quedas dos trabalhadores; reduzir a Maior apenas se houver sistema alternativo de proteção coletiva plenamente eficaz e a linha estiver desativada e sinalizada.',
  texto_fundamentacao_normativa = 'A linha de vida e seus pontos de ancoragem constituem o sistema de proteção contra quedas e devem ser projetados, instalados e inspecionados por profissional habilitado, com resistência compatível com os esforços de retenção de queda previstos. A exigência decorre da NR-35 (Trabalho em Altura), que determina que os sistemas de ancoragem sejam dimensionados e verificados, e do projeto/memorial de cálculo e da inspeção da obra. O critério "Projeto/inspeção, pontos de ancoragem ≥ resistência exigida" é requisito verificável: sem comprovação de projeto e de capacidade de carga, a linha de vida não pode ser aceita.',
  texto_risco_consequencia = 'Linha de vida instalada sem projeto/certificação ou com pontos de ancoragem de resistência inferior à exigida pode romper ou soltar-se sob a solicitação de uma queda, anulando o sistema de retenção justamente no momento crítico e resultando em queda livre com lesão grave ou fatal. A permanência da condição mantém a equipe conectada a um sistema não confiável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interditar o uso da linha de vida e obter/apresentar o projeto e o memorial de cálculo assinados por profissional habilitado, com a resistência mínima exigida para os pontos de ancoragem; (ii) inspecionar a instalação (fixações, tensionamento, conectores) e corrigir ou reinstalar os trechos não conformes; (iii) evidenciar a regularização com projeto, certificado/ART e registro fotográfico da instalação inspecionada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que a ancoragem estiver em estrutura não verificada ou abaixo do ponto exigido, aumentando o fator de queda; reduzir a Maior apenas se a estrutura for comprovadamente resistente e o desvio se limitar à altura do ponto com zona livre adequada.',
  texto_fundamentacao_normativa = 'O ponto de ancoragem do sistema de proteção individual deve estar em estrutura previamente verificada quanto à resistência e, sempre que possível, posicionado acima da cintura do trabalhador, de modo a reduzir o fator de queda e a distância de queda livre. A exigência decorre da NR-35 (Trabalho em Altura), que trata dos sistemas de ancoragem e da limitação da energia de impacto, e das boas práticas de segurança em altura. O critério "Estrutura verificada, ponto acima da cintura quando possível" é requisito verificável de aceitação da conexão do trabalhador.',
  texto_risco_consequencia = 'Ancorar o talabarte em estrutura não verificada (tubulação, guarda-corpo frágil, elemento improvisado) ou abaixo da cintura eleva o fator de queda e a distância de queda livre, podendo romper o ponto ou submeter o trabalhador a esforços e alturas incompatíveis com a zona livre de queda, com risco de choque contra o solo ou obstáculos. A permanência da condição mantém a conexão em ponto inadequado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar e verificar pontos de ancoragem em estrutura de resistência comprovada, preferencialmente acima da cintura, orientando a equipe quanto à conexão correta; (ii) desativar e sinalizar quaisquer pontos improvisados ou não verificados, instalando ancoragens adequadas onde necessário; (iii) evidenciar a correção com registro fotográfico da ancoragem regularizada e do trabalhador conectado ao ponto correto ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando cinturão, talabarte ou absorvedor estiverem danificados, vencidos ou incompatíveis com a zona livre de queda disponível; reduzir a Maior apenas em não conformidade documental (registro de inspeção) com o EPI íntegro e compatível.',
  texto_fundamentacao_normativa = 'O cinturão tipo paraquedista, o talabarte e o absorvedor de energia devem ser inspecionados antes do uso e ser compatíveis com a zona livre de queda disponível, de forma que, na retenção, o trabalhador não colida com o solo ou obstáculos inferiores. A exigência decorre da NR-35 (Trabalho em Altura) e da NR-06 (Equipamento de Proteção Individual), que impõem seleção, inspeção e uso adequado do EPI, além da especificação do fabricante. O critério "Inspecionados, compatíveis com zona livre de queda" é requisito verificável de aceitação do conjunto de proteção individual.',
  texto_risco_consequencia = 'O uso de cinturão, talabarte ou absorvedor danificados, vencidos ou incompatíveis com a zona livre de queda faz com que o sistema não interrompa a queda dentro da distância disponível, resultando em choque contra o solo ou obstáculos, ou em falha do EPI sob carga, com lesão grave ou fatal. A permanência da condição mantém a equipe protegida por EPI inadequado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher e inspecionar formalmente o cinturão, o talabarte e o absorvedor, substituindo os itens danificados, vencidos ou sem registro de inspeção; (ii) confrontar o comprimento do talabarte e a abertura do absorvedor com a zona livre de queda de cada frente, adotando conjunto compatível (por exemplo, talabarte retrátil onde a zona for reduzida); (iii) evidenciar a correção com a ficha de inspeção dos EPI e registro fotográfico do conjunto em uso ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trabalhador em altura efetivamente sem capacete com jugular ou com jugular solta em atividade sujeita a projeção/queda de objetos; manter Maior em não conformidade pontual prontamente sanável.',
  texto_fundamentacao_normativa = 'O capacete de segurança dotado de jugular (fixação sob o queixo) é obrigatório em toda atividade em altura, pois evita que o capacete se desprenda em caso de inclinação, deslocamento ou início de queda, mantendo a proteção da cabeça. A exigência decorre da NR-35 (Trabalho em Altura) e da NR-06 (Equipamento de Proteção Individual), que determinam o uso de capacete com jugular para trabalho em altura, e da especificação do fabricante. O critério "Obrigatório em toda atividade em altura" é requisito verificável de aceitação do EPI de cabeça.',
  texto_risco_consequencia = 'A ausência de capacete ou o uso sem a jugular ajustada permite que o equipamento se desprenda em um tropeço, inclinação ou queda, deixando a cabeça desprotegida contra impacto e agravando a gravidade de lesões cranioencefálicas em eventos de queda ou de projeção de objetos. A permanência da condição mantém os trabalhadores expostos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) fornecer e exigir o uso de capacete com jugular para todos os trabalhadores em altura, verificando o ajuste da tira sob o queixo; (ii) reforçar a orientação em diálogo de segurança (DDS) e incluir a verificação do capacete com jugular na inspeção diária da frente; (iii) evidenciar a correção com registro fotográfico dos trabalhadores em altura com capacete e jugular ajustados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver circulação de pessoas na projeção inferior sem isolamento e ferramentas/materiais soltos na altura; manter Maior quando a área inferior estiver isolada, reduzindo a exposição a terceiros.',
  texto_fundamentacao_normativa = 'Ferramentas e materiais utilizados em altura devem ser amarrados ou acondicionados de modo a impedir sua queda, prevenindo o atingimento de trabalhadores e terceiros na projeção inferior. A exigência decorre da NR-35 (Trabalho em Altura), que trata das medidas de proteção contra queda de materiais e ferramentas, e das boas práticas de organização da frente de trabalho. O critério "Prevenção de queda de materiais" é requisito verificável de aceitação da atividade em altura.',
  texto_risco_consequencia = 'Ferramentas e materiais não amarrados na altura podem cair sobre trabalhadores e terceiros na projeção inferior, provocando lesões graves ou fatais mesmo a partir de pequenas alturas, dado o alto valor da energia de impacto. A permanência da condição mantém a área sob a frente exposta à queda de objetos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) prover cabos/cordões de amarração, coldres e sacolas de ferramentas, amarrando todo item passível de queda e limitando o material na altura ao necessário; (ii) organizar a plataforma/andaime com rodapé e acondicionamento adequado, evitando peças soltas nas bordas; (iii) evidenciar a correção com registro fotográfico das ferramentas amarradas e da frente organizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trânsito de pessoas sob a frente em altura sem qualquer delimitação/sinalização; manter Maior quando o isolamento existir, porém com sinalização incompleta ou parcialmente deslocada.',
  texto_fundamentacao_normativa = 'A área situada sob a frente de trabalho em altura deve ser delimitada e sinalizada, impedindo a permanência e a circulação de pessoas na zona sujeita à queda de materiais, ferramentas ou do próprio trabalhador. A exigência decorre da NR-35 (Trabalho em Altura), que determina o isolamento e a sinalização da área sujeita à queda de materiais, ferramentas ou de pessoas sob a frente de trabalho, e das boas práticas de proteção de terceiros. O critério "Delimitação e sinalização sob a frente" é requisito verificável de aceitação do controle da área inferior.',
  texto_risco_consequencia = 'A ausência de isolamento e sinalização da área inferior permite que trabalhadores e terceiros permaneçam ou circulem na projeção da frente, ficando expostos à queda de materiais, ferramentas ou de pessoa, com risco de lesão grave ou fatal por impacto. A permanência da condição mantém a zona sob a frente acessível e desprotegida até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) isolar fisicamente a projeção inferior da frente com barreiras (fita/cerca/tapume) e afastar a circulação da zona de risco; (ii) instalar sinalização de advertência e, quando aplicável, designar sinaleiro/vigia para controle de acesso durante a atividade; (iii) evidenciar a correção com registro fotográfico da área inferior isolada e sinalizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver trabalhador em altura sem capacitação NR-35 válida (curso 8h/reciclagem bienal) ou sem ASO com aptidão para altura; reduzir a Maior apenas se a pendência for exclusivamente documental, com o trabalhador afastado da frente até a regularização.',
  texto_fundamentacao_normativa = 'Todo trabalhador que executa atividade em altura deve ser capacitado (curso de 8 horas com reciclagem periódica bienal) e considerado apto em avaliação médica ocupacional (ASO) específica para trabalho em altura. A exigência decorre da NR-35 (Trabalho em Altura), que estabelece a capacitação, a periodicidade da reciclagem e a exigência de aptidão médica para altura. O critério "Curso 8h + reciclagem bienal, ASO com aptidão para altura" é requisito verificável de habilitação do trabalhador para a atividade.',
  texto_risco_consequencia = 'Manter na frente trabalhador sem capacitação NR-35 válida ou sem ASO com aptidão para altura significa expor à altura pessoa que pode desconhecer o uso correto do sistema de proteção ou apresentar condição de saúde incompatível (por exemplo, labirintopatia), elevando a probabilidade de erro operacional, mal súbito e queda com lesão grave ou fatal. A permanência da condição mantém pessoal não habilitado exposto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar imediatamente da atividade em altura os trabalhadores sem capacitação ou ASO válidos; (ii) providenciar a capacitação/reciclagem NR-35 e o exame médico com aptidão para altura, atualizando a matriz de treinamentos e a documentação; (iii) evidenciar a regularização com certificados de capacitação, ASO e registro fotográfico da frente com equipe habilitada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver frente em altura ativa sem plano de resgate definido (equipe, equipamentos e tempo de resposta), dada a criticidade do trauma por suspensão; reduzir a Maior apenas com a frente paralisada até a estruturação do plano.',
  texto_fundamentacao_normativa = 'Deve existir plano de resgate e emergência para trabalho em altura, com equipe designada, equipamentos disponíveis e tempo de resposta compatível, de modo a permitir o socorro rápido de trabalhador retido pelo sistema de proteção após uma queda. A exigência decorre da NR-35 (Trabalho em Altura), que determina o planejamento do resgate e das medidas de emergência antes do início da atividade. O critério "Equipe, equipamentos e tempo de resposta definidos" é requisito verificável de aceitação da preparação para emergências.',
  texto_risco_consequencia = 'A ausência de plano de resgate estruturado faz com que um trabalhador retido pelo cinturão após uma queda permaneça suspenso sem socorro tempestivo, evoluindo para o trauma por suspensão (síndrome do arnês), quadro que pode ser fatal em poucos minutos. A permanência da condição mantém a frente sem capacidade de resposta a emergências até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar o plano de resgate específico da frente, designando equipe treinada, definindo os equipamentos de resgate e o tempo-alvo de resposta; (ii) disponibilizar e inspecionar os equipamentos de resgate no local e realizar simulado/treinamento da equipe; (iii) evidenciar a implantação com o plano documentado, registro do simulado e fotografia dos equipamentos de resgate posicionados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando houver atividade em altura em curso sob chuva, vento forte ou tempestade elétrica sem suspensão; reduzir a Maior quando as condições forem apenas limítrofes e houver monitoramento e critério de suspensão claramente definido e aplicado.',
  texto_fundamentacao_normativa = 'As condições climáticas devem ser avaliadas antes e durante o trabalho em altura, com suspensão da atividade em caso de chuva, vento excessivo, tempestade elétrica ou outras condições impeditivas que aumentem o risco de queda. A exigência decorre da NR-35 (Trabalho em Altura), que trata das condições impeditivas e da interrupção da atividade em situações de risco não controlado, e das boas práticas de segurança. O critério "Suspensão em chuva/vento/tempestade elétrica" é requisito verificável de aceitação das condições de execução.',
  texto_risco_consequencia = 'Executar trabalho em altura sob chuva, vento forte ou tempestade elétrica expõe o trabalhador a superfícies escorregadias, perda de equilíbrio, redução de visibilidade e risco de descarga atmosférica, elevando significativamente a probabilidade de queda com lesão grave ou fatal. A permanência da condição mantém a atividade em curso sob clima adverso até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a atividade em altura enquanto perdurarem as condições climáticas adversas, retirando a equipe para local seguro; (ii) definir e comunicar os critérios objetivos de suspensão e retorno (chuva, velocidade de vento, tempestade elétrica), com monitoramento contínuo durante a jornada; (iii) evidenciar a adequação com o registro do critério climático adotado e fotografia da frente com a atividade retomada em condição segura ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-08' and item_numero = 10;

-- ST-09 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de placa de EPI obrigatório ocorrer em frente com risco iminente (elétrico, altura ou içamento); reduzir a Menor se apenas uma placa de reforço estiver ausente em área de baixo risco.',
  texto_fundamentacao_normativa = 'A sinalização obrigatória de uso de EPI e as advertências por área comunicam ao trabalhador os riscos presentes e as medidas de proteção exigidas antes do acesso à frente de serviço. Aplicam-se a NR-06 (equipamentos de proteção individual), a NR-26 (sinalização de segurança) e a NR-18 (condições e meio ambiente de trabalho na construção), que exigem sinalização visível e adequada nos locais de trabalho, além do plano de sinalização do canteiro e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Uso de EPI, advertências por área" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência ou inadequação das placas obrigatórias faz o trabalhador acessar a área sem conhecer o EPI exigido nem os riscos presentes, aumentando a probabilidade de acidente por exposição não protegida e fragilizando a defesa da obra em eventual fiscalização ou perícia. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as frentes e áreas que exigem sinalização obrigatória, confrontando com o plano de sinalização e a matriz de riscos; (ii) instalar ou repor as placas de uso de EPI e de advertência nos acessos e pontos de exposição, com dimensão, altura e legibilidade adequadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar o mapa de sinalização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a frente não delimitada expuser terceiros ou a circulação de veículos e pedestres ao risco; manter em Menor se a delimitação existir mas estiver parcialmente deslocada em frente isolada.',
  texto_fundamentacao_normativa = 'A delimitação física por faixas e cones separa a frente ativa das áreas de circulação, restringe o acesso de pessoas não autorizadas e organiza o fluxo no canteiro. Aplicam-se a NR-18 (organização e isolamento das áreas de trabalho na construção) e as boas práticas de gestão de canteiro, complementadas pelo plano de sinalização e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Frentes ativas delimitadas" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Frente ativa sem faixas e cones permite a intrusão de trabalhadores e terceiros na zona de trabalho, expondo-os a quedas, atropelamentos e projeção de materiais, e dificulta a evacuação organizada em emergência. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar as frentes ativas sem delimitação ou com delimitação insuficiente; (ii) instalar faixas, fitas zebradas e cones contínuos no perímetro, garantindo visibilidade diurna e noturna e passagem segura para pedestres; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspecionar o perímetro, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de isolamento de áreas de alto risco (escavação, içamento e instalações energizadas); reduzir a Maior somente se o isolamento existir e a falha for de reforço ou de sinalização complementar.',
  texto_fundamentacao_normativa = 'O isolamento físico impede o acesso à zona de perigo de escavações (soterramento e queda), à área varrida por cargas suspensas e às instalações energizadas. Aplicam-se a NR-18 (escavações, movimentação e transporte de materiais e áreas de risco na construção) e a NR-10 (instalações e serviços em eletricidade), além do plano de içamento, do plano de sinalização e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Escavações, içamento, energizadas" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência de isolamento efetivo dessas áreas admite a permanência de pessoas em zonas de soterramento, de queda de carga e de contato ou arco elétrico, condições associadas a acidentes graves e fatais, mantendo o risco ativo enquanto não corrigido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) demarcar e isolar fisicamente cada área de risco (barreiras rígidas em escavações, cordão do raio de içamento e barreiras com placas nas áreas energizadas), restringindo o acesso a pessoal autorizado; (ii) associar a cada área a sinalização de proibição ou advertência compatível com o risco; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspecionar antes da liberação das frentes, para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando faltar identificação em área com agente de risco grave e iminente (radiação ionizante ou zona energizada); reduzir a Menor se a placa existir e apenas necessitar de reforço ou atualização.',
  texto_fundamentacao_normativa = 'A identificação dos riscos específicos (ruído, agentes químicos, elétrico e radiação) informa a natureza do agente presente e as precauções exigidas em cada área, em linha com o gerenciamento de riscos ocupacionais. Aplica-se a NR-26 (sinalização e advertência de segurança) e o Programa de Gerenciamento de Riscos da obra, complementados pelas especificações do projeto e pelas boas práticas de SSMA. O critério "Ruído, químicos, elétrico, radiação" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Sem a identificação do risco específico, o trabalhador desconhece o agente ao qual está exposto e deixa de adotar as precauções e o EPI corretos, elevando a probabilidade de dano à saúde (perda auditiva, intoxicação, choque, exposição à radiação) de forma cumulativa e muitas vezes silenciosa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear as áreas por agente de risco (ruído, químico, elétrico, radiação) a partir do PGR e das medições disponíveis; (ii) instalar placas específicas de identificação e advertência para cada agente, com pictograma e texto legíveis nos acessos e pontos de exposição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar o mapa de riscos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — risco elétrico com potencial de acidente fatal; reduzir a Maior apenas quando a área já estiver sinalizada e restrita e a falha for de complementação ou legibilidade.',
  texto_fundamentacao_normativa = 'A sinalização de perigo e a restrição de acesso às áreas elétricas advertem sobre o risco de choque e arco elétrico e limitam a aproximação a pessoal autorizado e capacitado. Aplicam-se a NR-10 (segurança em instalações e serviços em eletricidade) e a NR-26 (sinalização de segurança), que exigem identificação e advertência dos ambientes energizados, complementadas pelo projeto elétrico executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Placas de perigo, restrição de acesso" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A falta de sinalização e de restrição de acesso em área elétrica permite a aproximação de pessoas não autorizadas de partes energizadas, expondo-as a choque e arco elétrico, com potencial de queimaduras graves e óbito, além de descumprir a exigência de acesso controlado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os ambientes e equipamentos elétricos sem sinalização ou sem controle de acesso; (ii) instalar placas de perigo e de alta tensão e implementar a restrição de acesso (barreiras, trancas, identificação de pessoal autorizado) conforme a NR-10; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspecionar antes de energizar ou liberar a área, para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a área varrida por carga suspensa apresenta risco de queda de carga sobre pessoas; reduzir a Maior somente se o raio estiver demarcado e a falha for pontual de reposição.',
  texto_fundamentacao_normativa = 'A demarcação do raio de operação isola a zona sob e ao redor da carga suspensa, impedindo a permanência de pessoas na área varrida pelo equipamento e pela carga. Aplica-se a NR-18 (movimentação e transporte de materiais e áreas de risco na construção), complementada pelo plano de içamento e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Raio de operação demarcado" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Sem a demarcação do raio de içamento, trabalhadores podem permanecer sob a carga suspensa ou na zona de giro do equipamento, ficando expostos à queda de carga e a esmagamento, eventos de alta severidade e potencial fatalidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir e demarcar o raio de operação e a zona de exclusão a partir do plano de içamento; (ii) isolar o perímetro com cordão ou barreiras e sinaleiro dedicado, impedindo a circulação sob a carga durante a operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspecionar antes de cada manobra de içamento, para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a rota de fuga estiver ausente, obstruída ou ilegível em áreas de grande circulação ou de difícil evacuação; reduzir a Menor se faltar apenas sinalização complementar em trecho secundário.',
  texto_fundamentacao_normativa = 'A sinalização das rotas de fuga, com setas direcionais e indicação dos pontos de encontro, orienta a evacuação rápida e ordenada em emergência. Aplicam-se a NR-23 (proteção contra incêndios) e a NR-18 (saídas e circulação no canteiro), complementadas pelo plano de emergência da obra e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Setas e pontos de encontro visíveis" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Rotas de fuga não sinalizadas ou com sinalização ilegível retardam e desorganizam a evacuação em emergência (incêndio, colapso, vazamento), aumentando o risco de aglomeração, ferimentos e vítimas pela não localização das saídas e dos pontos de encontro. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o traçado das rotas de fuga e a localização dos pontos de encontro conforme o plano de emergência; (ii) instalar ou repor setas direcionais e placas de saída e de ponto de encontro, garantindo visibilidade, iluminação e desobstrução do percurso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e validar em simulado ou inspeção, para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver mapa afixado ou ele estiver desatualizado frente ao layout atual do canteiro; reduzir a Menor se estiver afixado e faltar cópia em ponto secundário.',
  texto_fundamentacao_normativa = 'O mapa de emergência afixado em pontos estratégicos comunica a todos os presentes as rotas, saídas, pontos de encontro e recursos de combate, sendo instrumento de resposta do plano de emergência. Sua manutenção decorre das boas práticas de gestão de SSMA e do plano de emergência da obra, devendo refletir o layout vigente do canteiro conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Atualizado, em pontos estratégicos" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência ou desatualização do mapa de emergência faz com que trabalhadores e visitantes não saibam para onde se dirigir em uma emergência, comprometendo a eficácia da evacuação e a rapidez do acionamento dos recursos, o que agrava as consequências do evento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar o mapa de emergência confrontando-o com o layout atual do canteiro e o plano de emergência; (ii) afixar o mapa atualizado em pontos estratégicos e de grande circulação, em suporte legível e protegido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e registrar a data da revisão, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a cor incorreta induzir erro de manobra em tubulação de fluido perigoso (gás, vapor, produto químico ou combate a incêndio); manter em Menor para divergências em linhas de baixo risco.',
  texto_fundamentacao_normativa = 'O padrão de cores de segurança identifica de forma imediata o conteúdo das tubulações e os elementos de segurança, prevenindo erros de operação e facilitando a resposta a emergências. Aplica-se a NR-26 (sinalização de segurança), expressamente referida no critério do item, que define as cores de segurança e sua aplicação, complementada pela especificação de identificação de tubulações do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Padrão de cores conforme NR-26" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Tubulações e elementos de segurança com cores fora do padrão induzem o operador a erro sobre o conteúdo e a função da linha, podendo resultar em manobra indevida, liberação de fluido perigoso ou atraso na identificação de recursos de emergência. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as tubulações e elementos com cores em desacordo com a NR-26 e a especificação do projeto; (ii) repintar ou reidentificar as linhas conforme o código de cores e aplicar as legendas e setas de sentido de fluxo onde exigido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar a legenda de cores, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando produtos perigosos estiverem sem rótulo ou com pictograma ilegível em áreas de manuseio ou armazenamento; reduzir a Menor para desgaste pontual de rótulo em produto de baixa periculosidade.',
  texto_fundamentacao_normativa = 'A rotulagem preventiva conforme o GHS, com rótulos e pictogramas legíveis, comunica os perigos, as precauções e as medidas de primeiros socorros de cada produto químico. Aplica-se a NR-26 (rotulagem preventiva de produtos químicos, que adota o Sistema Globalmente Harmonizado — GHS), acompanhada da exigência de disponibilização das fichas de dados de segurança (FDS/FISPQ), complementadas pelas especificações dos produtos aprovados na obra. O critério "Rótulos e pictogramas legíveis" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Produtos químicos sem rótulo GHS ou com pictograma ilegível impedem o trabalhador de reconhecer os perigos e as precauções, elevando o risco de manuseio incorreto, mistura indevida, intoxicação, queimadura química e resposta inadequada em caso de acidente ou derramamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar os produtos químicos e conferir rótulos, pictogramas GHS e disponibilidade das FDS/FISPQ; (ii) rerrotular ou substituir os rótulos ilegíveis ou ausentes conforme o GHS e assegurar as fichas de segurança acessíveis no local de uso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualizar o inventário químico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-09' and item_numero = 10;

-- ST-10 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o excesso de material estocado na frente obstruir rotas de fuga, acessos de emergência ou a própria execução do serviço',
  texto_fundamentacao_normativa = 'A frente de serviço deve conter apenas o material necessário à etapa em curso, mantendo o arranjo físico organizado e o fluxo de trabalho desimpedido. A NR-18 estabelece requisitos de organização, circulação e armazenamento de materiais nos canteiros de obra, condição reforçada pelo planejamento logístico do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que dimensiona o suprimento por frente. O critério "Sem estoque desnecessário na frente de serviço" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'O acúmulo de material sem uso imediato na frente de serviço reduz a área útil de trabalho, dificulta a circulação segura, favorece tropeços e quedas de mesmo nível e expõe insumos a intempéries e danos, com perdas de material e queda de produtividade. A permanência da condição mantém a frente congestionada e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remover da frente o material que exceda a necessidade da etapa, remanejando-o para o local de estocagem definido no arranjo físico do canteiro; (ii) reprogramar o suprimento por frente conforme o cronograma de execução, evitando entregas antecipadas; (iii) evidenciar a organização resultante com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a sucata contiver material cortante, perfurante ou contaminante disposto fora de baia e sem remoção periódica',
  texto_fundamentacao_normativa = 'A sucata e os resíduos gerados devem ser segregados em baia específica, com remoção periódica que impeça o acúmulo no canteiro. Aplicam-se a NR-18, quanto à ordem e limpeza do canteiro, e as boas práticas de gerenciamento de resíduos da construção civil, que orientam a segregação por classe e a destinação controlada; o Plano de Gerenciamento de Resíduos da obra e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, definem os pontos de coleta. O critério "Baia específica, remoção periódica" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A sucata não segregada e sem remoção periódica ocupa áreas de trabalho e circulação, cria pontos de acúmulo com risco de cortes, perfurações e incêndio, atrai vetores e compromete a destinação correta dos resíduos, com passivo ambiental e de segurança. A permanência da condição mantém o resíduo disperso e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) segregar a sucata na baia específica, separando-a por classe de resíduo conforme o plano de gerenciamento da obra; (ii) estabelecer e cumprir rotina de remoção periódica para destinação controlada, evitando novo acúmulo; (iii) evidenciar a baia organizada e a remoção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver madeiras com pregos expostos em áreas de trânsito de pessoas, acessos ou plataformas de trabalho',
  texto_fundamentacao_normativa = 'As madeiras retiradas de fôrmas, escoramentos ou embalagens devem ter os pregos removidos ou rebatidos antes de seu empilhamento, reaproveitamento ou descarte. A NR-18 estabelece requisitos de ordem, limpeza e organização do canteiro aplicáveis ao manuseio e ao empilhamento de materiais, e as boas práticas de desforma orientam a retirada ou o rebatimento dos pregos das madeiras antes do reaproveitamento, empilhamento ou descarte. O critério "Pregos removidos ou rebatidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Madeiras com pregos expostos representam risco direto de perfuração de pés e mãos, ferimentos por contato e possibilidade de tétano, além de dificultarem o manuseio e o empilhamento seguros do material. A permanência da condição mantém pontos perfurantes ativos nas áreas de trabalho e circulação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar as madeiras desformadas e remover ou rebater todos os pregos expostos antes de empilhá-las ou destiná-las; (ii) padronizar a operação de despregar na própria etapa de desforma, mantendo bancada e ferramenta adequadas para o serviço; (iii) evidenciar as madeiras isentas de pregos expostos com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver cabos elétricos energizados no piso, em travessias sem proteção ou expostos a tráfego e água',
  texto_fundamentacao_normativa = 'Os cabos elétricos e mangueiras devem permanecer organizados, suspensos ou protegidos mecanicamente nas travessias de vias e áreas de circulação, evitando contato com o piso, tráfego e umidade. A NR-18, quanto às instalações elétricas provisórias e à proteção de condutores, e as boas práticas de organização do canteiro orientam a suspensão e a proteção nas travessias; o projeto de instalações provisórias da obra define os traçados. O critério "Suspensos ou protegidos em travessias" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Cabos e mangueiras dispostos no piso e desprotegidos nas travessias criam risco de tropeço e queda, danos mecânicos e esmagamento por veículos e, no caso de cabos elétricos, risco de choque elétrico por dano à isolação em contato com umidade. A permanência da condição mantém os condutores vulneráveis e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender os cabos e mangueiras em suportes adequados ou protegê-los com canaleta/passa-cabo nas travessias sujeitas a tráfego; (ii) reorganizar os traçados conforme o projeto de instalações provisórias, eliminando trechos soltos no piso e em poças; (iii) evidenciar a organização e a proteção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o entulho acumulado obstruir rotas de circulação, saídas de emergência ou sobrecarregar lajes e plataformas',
  texto_fundamentacao_normativa = 'O entulho gerado deve ser removido continuamente das frentes de serviço e das áreas de circulação, mantendo-as limpas e desobstruídas. A NR-18 estabelece requisitos de ordem e limpeza do canteiro e de remoção regular de entulho, condição reforçada pelas boas práticas de gerenciamento de resíduos da construção civil. O critério "Sem acúmulo em circulação e frentes" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'O acúmulo de entulho nas frentes e nas vias de circulação reduz as áreas de trabalho e de passagem, gera risco de tropeço, quedas e soterramento, pode sobrecarregar estruturas provisórias e dificulta o acesso em emergências. A permanência da condição mantém as áreas obstruídas e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remover o entulho acumulado das frentes e vias, destinando-o aos pontos de coleta e à disposição controlada; (ii) instituir rotina de remoção contínua ao longo da jornada, evitando novo acúmulo nas áreas de trabalho; (iii) evidenciar as áreas limpas e desobstruídas com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a obstrução da drenagem provocar empoçamento em áreas de trabalho, risco elétrico ou instabilidade de taludes e fundações',
  texto_fundamentacao_normativa = 'As canaletas, caixas e demais dispositivos de drenagem provisória do canteiro devem permanecer desobstruídos e limpos, garantindo o escoamento e impedindo o empoçamento de água. Aplicam-se a NR-18, quanto à ordem, limpeza e organização do canteiro, e as boas práticas de drenagem provisória, detalhadas no projeto de drenagem da obra, projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define traçados e caimentos. O critério "Canaletas e caixas limpas, sem empoçamento" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A drenagem obstruída provoca empoçamento e alagamento de áreas de trabalho e circulação, favorece a proliferação de vetores, aumenta o risco de escorregões e de choque elétrico junto a instalações provisórias e pode saturar o solo, comprometendo taludes, escavações e fundações. A permanência da condição mantém o acúmulo de água e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) limpar e desobstruir canaletas, caixas e bocas de lobo, removendo sedimentos e detritos que impeçam o escoamento; (ii) restabelecer os caimentos e o traçado da drenagem provisória conforme o projeto, corrigindo pontos de empoçamento; (iii) evidenciar o escoamento restabelecido com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a via obstruída for rota de fuga, acesso de emergência ou única passagem de evacuação',
  texto_fundamentacao_normativa = 'Os corredores, acessos e vias de circulação do canteiro devem permanecer permanentemente livres e desimpedidos, assegurando o trânsito seguro de pessoas e a evacuação em emergências. A NR-18 estabelece requisitos para as áreas de vivência e de circulação e para a manutenção de acessos desobstruídos, condição reforçada pelo layout do canteiro do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Corredores e acessos desimpedidos" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Passagens obstruídas por materiais, equipamentos ou entulho impedem o trânsito seguro, forçam desvios inseguros e comprometem a evacuação e o socorro em situações de emergência, agravando as consequências de um acidente ou princípio de incêndio. A permanência da condição mantém as rotas comprometidas e o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) desobstruir imediatamente corredores e acessos, removendo materiais e obstáculos das faixas de circulação; (ii) delimitar e sinalizar as vias conforme o layout do canteiro, coibindo a reocupação das passagens; (iii) evidenciar as vias livres e sinalizadas com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o empilhamento estiver instável, com altura excessiva ou próximo a pessoas, vias e bordas de laje',
  texto_fundamentacao_normativa = 'O empilhamento de materiais deve respeitar limites de altura e condições de estabilidade e amarração que impeçam o tombamento e o desmoronamento das pilhas. Aplicam-se a NR-11, quanto ao armazenamento e empilhamento seguro de materiais, e a NR-18, quanto à organização do canteiro; as recomendações do fabricante e do projeto de logística do canteiro complementam os limites aplicáveis. O critério "Altura e amarração adequadas" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Pilhas com altura excessiva, base irregular ou sem amarração adequada podem tombar ou desmoronar, atingindo trabalhadores e equipamentos, além de danificar o material estocado e obstruir áreas de circulação. A permanência da condição mantém a pilha instável e o risco de soterramento e esmagamento ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) refazer o empilhamento respeitando a altura máxima e a base estável, com amarração ou travamento quando aplicável; (ii) afastar as pilhas de vias de circulação, bordas de laje e áreas de permanência de pessoas, observando as recomendações do fabricante; (iii) evidenciar o empilhamento estável e organizado com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor em caso de reincidência ou quando a frente for entregue suja de forma a comprometer a inspeção ou a etapa seguinte',
  texto_fundamentacao_normativa = 'Ao fim de cada jornada, a frente de serviço deve ser entregue limpa e organizada, com o recolhimento de ferramentas, sobras e resíduos, prática de housekeeping que sustenta a ordem e a segurança do canteiro. A NR-18, quanto à ordem e limpeza permanentes do canteiro, e as boas práticas de gestão de SSMA orientam a arrumação ao término do turno. O critério "Frente entregue limpa ao fim da jornada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A frente não organizada ao fim do turno acumula sobras, ferramentas e resíduos, expondo a próxima equipe a riscos de tropeço, cortes e quedas, dificultando a inspeção e a continuidade dos serviços e favorecendo perdas e extravios de material. A permanência da condição perpetua a desordem entre turnos e mantém o risco ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o housekeeping ao término da jornada, recolhendo ferramentas, sobras e resíduos e destinando-os aos locais apropriados; (ii) padronizar a rotina de arrumação pós-turno como condição de encerramento da frente, com verificação pela liderança; (iii) evidenciar a frente entregue limpa com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-10' and item_numero = 9;

-- ST-11 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver transporte manual de carga acima dos limites de referência sem meio auxiliar, com trabalhador já apresentando queixa musculoesquelética.',
  texto_fundamentacao_normativa = 'O levantamento, transporte e descarga manual de cargas deve observar peso, frequência e distância compatíveis com a capacidade do trabalhador, priorizando meios auxiliares (carrinhos, paleteiras, dispositivos de içamento). Aplica-se a NR-17 (Ergonomia), que trata expressamente do transporte manual de cargas e da adequação da tarefa ao trabalhador. O critério "Peso e frequência adequados, uso de meios auxiliares" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da condição de trabalho, complementado pelo programa de gerenciamento de riscos da obra.',
  texto_risco_consequencia = 'O manuseio manual de cargas excessivas ou repetitivas sem meios auxiliares expõe o trabalhador a lesões lombares e osteomusculares agudas e crônicas (LER/DORT), afastamentos e incapacidade, além de comprometer a produtividade da frente de serviço. A permanência da condição mantém a sobrecarga biomecânica ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reavaliar a tarefa quanto a peso, frequência e distância de transporte, redimensionando cargas unitárias e fracionando o material quando possível; (ii) disponibilizar e exigir o uso de meios auxiliares de movimentação (carrinhos, paleteiras, dispositivos de içamento) e capacitar a equipe na técnica correta de levantamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos meios auxiliares em uso e revisão da avaliação ergonômica da tarefa, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a postura extrema (agachamento, torção ou braços acima dos ombros) for mantida de forma prolongada e recorrente, sem qualquer alternância ou rodízio.',
  texto_fundamentacao_normativa = 'A organização do trabalho deve permitir alternância de postura e evitar a manutenção prolongada de posturas extremas ou desfavoráveis (agachamento, torção de tronco, trabalho acima da linha dos ombros). Aplica-se a NR-17 (Ergonomia), que exige a adaptação das condições de trabalho às características psicofisiológicas do trabalhador. O critério "Alternância de postura, sem posturas extremas prolongadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, apoiado na avaliação ergonômica das atividades.',
  texto_risco_consequencia = 'A manutenção de posturas estáticas ou extremas por tempo prolongado provoca fadiga muscular, dores articulares e evolução para distúrbios osteomusculares relacionados ao trabalho (DORT), com queda de rendimento, erros de execução e afastamentos. A permanência da condição mantém a exigência postural inadequada ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reorganizar a tarefa para permitir alternância de postura e introduzir rodízio de função ou micropausas nas atividades com exigência postural elevada; (ii) adequar a altura do plano de trabalho, disponibilizar apoios e reposicionar o material para eliminar torções e alcances excessivos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das posturas adequadas e da nova organização do posto, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando houver exposição a calor (IBUTG elevado) sem regime de pausas, pelo risco imediato de sobrecarga térmica; reduzir a Maior apenas se a atividade for pesada sem componente térmico relevante.',
  texto_fundamentacao_normativa = 'Atividades pesadas ou realizadas sob sobrecarga térmica exigem regime de pausas de recuperação dimensionado conforme a intensidade do esforço e a exposição ao calor. Aplicam-se a NR-17 (Ergonomia), quanto às pausas em atividades que demandam sobrecarga muscular ou térmica, e a NR-15 e seu Anexo 3 (exposição ao calor), que estabelece limites e o regime de trabalho-descanso com base no IBUTG. O critério "Pausas de recuperação implementadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da condição de trabalho.',
  texto_risco_consequencia = 'A ausência de pausas de recuperação em atividade pesada ou sob calor conduz à fadiga acumulada, desidratação, câimbras, exaustão e, no limite, intermação (heat stroke), com risco de acidente por perda de atenção e de agravos à saúde do trabalhador. A permanência da condição mantém a sobrecarga fisiológica e térmica ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) estabelecer e afixar o regime de pausas de recuperação dimensionado pela intensidade da atividade e pela medição de IBUTG, com local sombreado/climatizado para descanso e disponibilização de água potável; (ii) reprogramar as tarefas mais pesadas para os horários de menor carga térmica e revezar a equipe; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da área de descanso e do quadro de pausas, anexando a medição de IBUTG, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o mobiliário inadequado do escritório de obra atingir postos de uso contínuo (administração, engenharia, apontamento) gerando queixas osteomusculares reiteradas.',
  texto_fundamentacao_normativa = 'Os postos de trabalho administrativos do canteiro (escritório de obra) devem dispor de mobiliário adequado — cadeiras reguláveis, monitores em altura correta e apoios — que permita postura confortável durante o trabalho sentado. Aplica-se a NR-17 (Ergonomia), que estabelece parâmetros para mobiliário, assento, superfície de trabalho e disposição de monitores nos postos de trabalho. O critério "Escritório de obra: cadeiras, monitores, apoios" integra o plano de inspeção da obra e constitui requisito verificável de aceitação dos postos administrativos.',
  texto_risco_consequencia = 'Mobiliário inadequado nos postos administrativos do canteiro impõe posturas forçadas ao pescoço, coluna e membros superiores, favorecendo cervicalgias, lombalgias, fadiga visual e distúrbios osteomusculares em atividades de longa permanência sentada, com absenteísmo e queda de desempenho. A permanência da condição mantém a inadequação ergonômica do posto ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir ou regular as cadeiras para altura, encosto e apoio adequados, e reposicionar os monitores na altura da linha dos olhos e à distância confortável; (ii) prover apoios necessários (apoio para pés, suporte de documentos, apoio de punho) e organizar a superfície de trabalho conforme os parâmetros ergonômicos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos postos readequados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a avaliação ergonômica estiver ausente em obra com atividades reconhecidamente críticas (levantamento de cargas, sobrecarga térmica, movimentos repetitivos), configurando descumprimento de requisito legal.',
  texto_fundamentacao_normativa = 'A obra deve dispor de avaliação ergonômica das atividades — avaliação ergonômica preliminar e, quando indicada, Análise Ergonômica do Trabalho (AET) — que identifique riscos e subsidie medidas de adequação. Aplica-se a NR-17 (Ergonomia), que prevê a avaliação ergonômica preliminar e a AET como instrumentos de diagnóstico e de definição das ações. O critério "Avaliação ergonômica preliminar realizada" integra o plano de inspeção da obra e o programa de gerenciamento de riscos, constituindo requisito documental verificável de aceitação da gestão ergonômica.',
  texto_risco_consequencia = 'A inexistência de avaliação ergonômica impede a identificação e o tratamento sistemático dos riscos ergonômicos, deixando as tarefas críticas sem medidas de controle definidas e expondo os trabalhadores a agravos osteomusculares não gerenciados, além de fragilizar juridicamente a obra perante fiscalização. A permanência da condição mantém a lacuna de diagnóstico ergonômico ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar a avaliação ergonômica preliminar das atividades da obra, por profissional habilitado, priorizando as tarefas com maior exigência física; (ii) desdobrar a AET nas situações em que a avaliação preliminar indicar necessidade, com plano de ação e prazos para as medidas corretivas; (iii) evidenciar a correção anexando o documento de avaliação ergonômica e registro fotográfico ({{evidencia_foto_correcao}}) das medidas implementadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ferramenta inadequada gerar vibração mão-braço significativa ou esforço repetitivo elevado em atividade contínua, com potencial de dano à saúde.',
  texto_fundamentacao_normativa = 'As ferramentas e equipamentos devem ser adequados à tarefa e ao trabalhador, reduzindo esforço físico, força de preensão e transmissão de vibração. Aplica-se a NR-17 (Ergonomia), quanto à adequação de máquinas, ferramentas e equipamentos às características do trabalhador e à tarefa; quando houver exposição relevante a vibração, o controle deve ser dimensionado no âmbito da avaliação e controle das exposições ocupacionais a agentes físicos (NR-09) e das especificações técnicas do fabricante. O critério "Reduzem esforço e vibração" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das ferramentas empregadas.',
  texto_risco_consequencia = 'O uso de ferramentas inadequadas à tarefa aumenta o esforço muscular, a força de preensão e a exposição a vibração mão-braço, favorecendo fadiga, tendinites, síndrome do túnel do carpo e distúrbios vasculares e neurológicos por vibração, além de reduzir a precisão e a segurança da operação. A permanência da condição mantém a sobrecarga biomecânica e vibratória ativa até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) selecionar ferramentas apropriadas à tarefa, com pega ergonômica, peso adequado e, quando aplicável, sistema de amortecimento de vibração conforme especificação do fabricante; (ii) implementar rodízio e limitar o tempo de exposição contínua às ferramentas vibratórias, provendo EPI e manutenção preventiva; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das ferramentas adequadas em uso e da ficha de manutenção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-11' and item_numero = 6;

-- ST-12 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o combustível estiver estocado próximo a fontes de ignição, sem ventilação ou junto a alojamentos, frentes de serviço ou vias de circulação.',
  texto_fundamentacao_normativa = 'O armazenamento de líquidos combustíveis deve ocorrer em local específico, ventilado e afastado de fontes de calor e ignição, condição de controle do risco de incêndio e explosão em canteiro de obra. Aplicam-se a NR-20 (Segurança e Saúde no Trabalho com Inflamáveis e Combustíveis), que estabelece requisitos de instalação e armazenamento, e a NBR 17505 (armazenamento de líquidos inflamáveis e combustíveis), que define afastamentos, ventilação e classificação das áreas. O critério "Área específica, ventilada, afastada de ignição" integra o plano de inspeção e constitui requisito verificável de aceitação da condição de armazenagem, observado o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}.',
  texto_risco_consequencia = 'O armazenamento inadequado de combustíveis permite o acúmulo de vapores e a proximidade de fontes de ignição, criando condição favorável a princípio de incêndio ou explosão, com risco de queimaduras graves, danos ao patrimônio e paralisação da obra. A permanência da condição mantém ativo o risco de sinistro enquanto não corrigida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) transferir o combustível para área específica delimitada, ventilada e sinalizada, afastada de fontes de calor, ignição e de áreas de circulação e vivência; (ii) reordenar recipientes sobre piso impermeável com contenção e garantir ventilação natural cruzada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trincas, ausência de bacia ou volume insuficiente que permita vazamento livre para o solo, drenagem ou curso d''água.',
  texto_fundamentacao_normativa = 'Tanques de líquidos combustíveis devem dispor de bacia de contenção estanque, com volume compatível com o maior reservatório contido e sem trincas, de modo a reter derramamentos e evitar contaminação do solo. Aplicam-se a NR-20, quanto às medidas de contenção e prevenção de vazamentos, e a NBR 17505 (armazenamento de líquidos inflamáveis e combustíveis), que dimensiona a capacidade e a estanqueidade da contenção secundária. O critério "Volume compatível, sem trincas" integra o plano de inspeção e constitui requisito verificável de aceitação da instalação de armazenamento.',
  texto_risco_consequencia = 'Bacia de contenção inexistente, subdimensionada ou trincada não retém o produto em caso de vazamento, permitindo a dispersão de combustível pelo solo e drenagens, com contaminação ambiental, formação de poça inflamável e passivo ambiental de reparação onerosa. A permanência da condição mantém o tanque sem barreira secundária efetiva. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recuperar ou executar a bacia de contenção estanque com volume compatível com o maior tanque contido, tratando trincas e juntas; (ii) verificar a estanqueidade por inspeção visual e, quando aplicável, por ensaio de estanqueidade, mantendo o sistema de drenagem controlado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — operação de abastecimento com potencial imediato de ignição por eletricidade estática ou derramamento; manter Crítica salvo evidência de todos os controles ativos e operação assistida.',
  texto_fundamentacao_normativa = 'A operação de abastecimento deve ser realizada com o motor desligado, com aterramento/equipotencialização entre o recipiente e o equipamento e com kit de contenção de emergência próximo, controlando a ignição por eletricidade estática e a resposta a pequenos derramamentos. Aplica-se a NR-20, que estabelece procedimentos operacionais e medidas de controle nas atividades com inflamáveis e combustíveis, complementada pelo procedimento de abastecimento e pela ficha de segurança do produto. O critério "Motor desligado, aterramento, kit contenção próximo" integra o plano de inspeção e constitui requisito verificável de aceitação da operação.',
  texto_risco_consequencia = 'Abastecimento com motor ligado, sem aterramento ou sem kit de contenção pode gerar centelha ou faísca por eletricidade estática junto a vapores inflamáveis, resultando em incêndio ou explosão durante a operação, com risco de queimaduras graves ao operador e a terceiros. A permanência da condição expõe cada abastecimento a ignição não controlada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instituir e treinar procedimento de abastecimento com motor obrigatoriamente desligado, cabo de aterramento/equipotencialização conectado e área isolada; (ii) posicionar kit de contenção de emergência e extintor apropriado ao alcance do ponto de abastecimento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando cilindros estiverem deitados, soltos, expostos ao sol ou próximos a oxidantes/comburentes, com risco de queda, aquecimento ou reação.',
  texto_fundamentacao_normativa = 'Cilindros de GLP e demais gases inflamáveis devem permanecer na posição vertical, presos contra quedas, protegidos da incidência solar direta e segregados de gases oxidantes e comburentes, condições que reduzem o risco de vazamento, aquecimento e reação perigosa. Aplicam-se a NR-20, quanto ao armazenamento e manuseio de gases inflamáveis, e a NBR 15514 (área de armazenamento de recipientes transportáveis de GLP), que define separação, ventilação e afastamento dos recipientes. O critério "Em pé, presos, separados de oxidantes, sombra" integra o plano de inspeção e constitui requisito verificável de aceitação da armazenagem de cilindros.',
  texto_risco_consequencia = 'Cilindros tombados, soltos, ao sol ou próximos de oxidantes podem sofrer queda com ruptura da válvula, sobrepressão por aquecimento ou reação com comburentes, culminando em vazamento, jato de fogo ou explosão (BLEVE), com risco à vida dos trabalhadores no entorno. A permanência da condição mantém o cilindro em estado inseguro de armazenagem. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) posicionar todos os cilindros na vertical, fixados por corrente ou cinta em suporte estável, com capacete/protetor de válvula colocado; (ii) segregar os inflamáveis dos gases oxidantes/comburentes, sombrear a área e assegurar ventilação natural; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver extintor na área de inflamáveis, ou o tipo/capacidade for incompatível com a classe de fogo, ou os equipamentos estiverem vencidos/inacessíveis.',
  texto_fundamentacao_normativa = 'A área de inflamáveis deve dispor de extintores em tipo e quantidade compatíveis com a classe de fogo dos produtos armazenados, sinalizados, desobstruídos e dentro da validade, garantindo resposta imediata a princípio de incêndio. Aplicam-se a NR-23 (Proteção Contra Incêndios), quanto à existência e adequação dos meios de combate, e a NBR 12693 (sistemas de proteção por extintores de incêndio), que define seleção, distribuição e capacidade extintora. O critério "Tipo e quantidade adequados" integra o plano de inspeção e constitui requisito verificável de aceitação da proteção contra incêndio na área.',
  texto_risco_consequencia = 'A ausência ou inadequação de extintores na área de inflamáveis retira o meio de combate imediato a um princípio de incêndio, permitindo a rápida evolução do fogo para sinistro de grande porte, com risco de vítimas, perda total do armazenamento e propagação para o entorno. A permanência da condição deixa a área sem resposta inicial adequada ao incêndio. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) dimensionar e instalar extintores de classe e capacidade compatíveis com os produtos armazenados, na quantidade e distribuição adequadas; (ii) sinalizar, desobstruir e verificar a validade/carga e a inspeção periódica dos equipamentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a supressão de fontes de ignição e o controle de trabalho a quente são barreiras primárias; manter Crítica enquanto houver sinalização ausente ou trabalho a quente sem permissão emitida.',
  texto_fundamentacao_normativa = 'A área de inflamáveis deve ostentar sinalização de proibição de fontes de ignição (placas "Proibido Fumar" e correlatas) e submeter toda atividade com chama, centelha ou calor a Permissão de Trabalho a Quente, controlando a introdução de energia de ignição em atmosfera potencialmente inflamável. Aplicam-se a NR-20, que exige a análise e a autorização das atividades a quente e o controle das fontes de ignição, e a NR-26 (Sinalização de Segurança), quanto à padronização das placas. O critério "Placas ''Proibido Fumar'', permissão para trabalho a quente" integra o plano de inspeção e constitui requisito verificável de aceitação da gestão de ignição na área.',
  texto_risco_consequencia = 'A falta de sinalização proibitiva e de controle formal do trabalho a quente permite a introdução de chama, centelha ou brasa em ambiente com vapores inflamáveis, resultando em ignição imediata, incêndio ou explosão, com risco de morte para os trabalhadores presentes. A permanência da condição mantém a atmosfera de risco exposta a fontes de ignição não controladas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar sinalização padronizada de proibição de fumar e de fontes de ignição nos acessos e no perímetro da área; (ii) implantar e exigir a Permissão de Trabalho a Quente, com análise de risco, medição de atmosfera e vigia de fogo para qualquer atividade com calor; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando trabalhador operar a instalação de inflamáveis sem a capacitação NR-20 compatível com a classe da instalação, ou com certificação vencida.',
  texto_fundamentacao_normativa = 'Os trabalhadores que atuam com inflamáveis e combustíveis devem possuir capacitação específica prevista na NR-20, com conteúdo e carga horária compatíveis com a classe da instalação (I, II ou III), condição habilitante para a operação segura e para a resposta a emergências. Aplica-se diretamente a NR-20 (Segurança e Saúde no Trabalho com Inflamáveis e Combustíveis), que define a obrigatoriedade, o conteúdo e a periodicidade da capacitação conforme a classificação da instalação. O critério "Curso compatível com a classe da instalação" integra o plano de inspeção e constitui requisito verificável de aceitação da habilitação da equipe.',
  texto_risco_consequencia = 'Trabalhadores sem a capacitação NR-20 compatível desconhecem os procedimentos operacionais, os riscos e as ações de emergência da instalação, elevando a probabilidade de erro operacional que culmine em vazamento, incêndio ou explosão, com risco à própria vida e à de terceiros. A permanência da condição mantém a operação conduzida por pessoal não habilitado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar a classe da instalação e identificar os trabalhadores sem capacitação NR-20 compatível ou com certificado vencido; (ii) providenciar a capacitação/reciclagem no nível exigido, afastando da atividade quem não estiver habilitado até a conclusão; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia dos certificados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a indisponibilidade da FISPQ envolver produto de alto risco ou impedir a resposta correta a vazamento, contato ou incêndio.',
  texto_fundamentacao_normativa = 'As Fichas de Informações de Segurança de Produtos Químicos (FISPQ) devem estar disponíveis e acessíveis no local de armazenamento, fornecendo dados de perigo, manuseio, EPI, primeiros socorros e combate a incêndio de cada produto. Aplicam-se a NBR 14725 (produtos químicos — informações sobre segurança, saúde e meio ambiente / FISPQ), quanto ao conteúdo e formato da ficha, em conjunto com o programa de gerenciamento de produtos químicos da obra. O critério "Acessíveis no local de armazenamento" integra o plano de inspeção e constitui requisito verificável de aceitação da gestão de informação de segurança química.',
  texto_risco_consequencia = 'A indisponibilidade da FISPQ no local impede a consulta rápida às medidas de manuseio, proteção e resposta a emergência do produto, retardando ou tornando inadequada a atuação em caso de vazamento, contato ou incêndio, com agravamento de lesões e da extensão do acidente. A permanência da condição mantém a equipe sem a informação de segurança do produto no ponto de uso. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reunir as FISPQ atualizadas de todos os produtos armazenados e mantê-las em pasta/quadro acessível no próprio local de armazenamento; (ii) divulgar às equipes a localização e o uso da FISPQ, alinhando-a aos procedimentos de emergência e à sinalização de rotulagem; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-12' and item_numero = 8;

-- ST-13 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver execução de trabalho a quente sem Permissão de Trabalho (PT) válida ou com material combustível dentro do raio de 10 m; rebaixar a Maior apenas quando a PT existir e a área estiver livre, restando pendência formal sanável (assinatura/validade) sem exposição a combustível.',
  texto_fundamentacao_normativa = 'A Permissão de Trabalho (PT) é o controle documental que autoriza o trabalho a quente somente após análise de risco da área e liberação, condicionada à inspeção de um raio de 10 m livre de materiais combustíveis. Solda, corte e esmerilhamento produzem fagulhas, respingos incandescentes e escória que percorrem distâncias e persistem quentes, exigindo liberação prévia e isolamento da área. Aplicam-se a NR-18 (segurança e saúde no trabalho na indústria da construção) e as boas práticas de gestão de trabalho a quente, além do plano de resposta a emergência da obra; o critério "PT emitida com análise da área (raio de 10 m livre de combustíveis)" integra o plano de inspeção e constitui requisito verificável de liberação da tarefa.',
  texto_risco_consequencia = 'A execução de trabalho a quente sem PT válida ou com combustíveis no raio de 10 m expõe a obra a princípio de incêndio e explosão por ignição de fagulhas e escória, com risco de queimaduras graves, perdas materiais e paralisação. A permanência da condição mantém a tarefa liberada indevidamente e o cenário de ignição ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender imediatamente o trabalho a quente até emissão e liberação de PT específica, com análise de risco da tarefa e do local; (ii) inspecionar e liberar o raio de 10 m, removendo, protegendo ou umidificando materiais combustíveis, e registrar a liberação na PT; (iii) evidenciar a correção com registro fotográfico da área liberada e da PT assinada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trabalhadores, instalações ou materiais combustíveis adjacentes expostos diretamente a fagulhas ou radiação sem anteparo; manter Maior quando a exposição for restrita e sem terceiros no entorno.',
  texto_fundamentacao_normativa = 'O anteparo ou biombo de proteção confina fagulhas, respingos e escória e bloqueia a radiação luminosa e ultravioleta gerada na solda e no corte, protegendo trabalhadores vizinhos e impedindo a projeção de material incandescente para áreas adjacentes. O critério "contenção de fagulhas e radiação" é boa prática consolidada de trabalho a quente e integra o plano de inspeção da obra; sua adoção decorre da NR-18 (segurança na indústria da construção) e das medidas coletivas de proteção previstas no planejamento de SSMA, constituindo requisito verificável de aceitação da montagem do posto de trabalho.',
  texto_risco_consequencia = 'A ausência de anteparo permite a projeção de fagulhas e escória para além do posto e a exposição de terceiros à radiação do arco, com risco de início de incêndio em áreas vizinhas, queimaduras e ceratoconjuntivite ("olho de solda") em trabalhadores não protegidos. A permanência da condição mantém o entorno exposto até a instalação da barreira. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar anteparo ou biombo em material não combustível dimensionado para conter fagulhas e bloquear a radiação, delimitando o posto de trabalho; (ii) reposicionar a proteção sempre que a frente de serviço se deslocar, mantendo o isolamento do entorno; (iii) evidenciar a correção com registro fotográfico do biombo instalado em posição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando não houver extintor adequado e operante junto ao ponto de trabalho, ou ausência de observador de fogo onde exigido; rebaixar a Maior apenas quando o extintor existir e estiver operante, restando não conformidade de posicionamento ou sinalização de fácil correção imediata.',
  texto_fundamentacao_normativa = 'O extintor de incêndio posicionado no ponto de trabalho é o meio de combate imediato a princípio de incêndio deflagrado por fagulhas ou escória, e o observador de fogo (vigia) assegura resposta rápida quando a natureza da tarefa ou do local o exige. Aplicam-se a NR-23 (proteção contra incêndios), que trata da disponibilidade e do acesso a equipamentos de combate a incêndio, e a NR-18 no contexto da construção, além do plano de emergência da obra. O critério "extintor no ponto de trabalho, observador de fogo quando exigido" integra o plano de inspeção e constitui requisito verificável de liberação do trabalho a quente.',
  texto_risco_consequencia = 'A falta de extintor operante junto ao ponto de trabalho, ou de observador de fogo quando exigido, retira o meio de combate imediato e retarda a resposta a um foco de incêndio, permitindo sua propagação com risco de queimaduras, perdas materiais e evacuação da frente de serviço. A permanência da condição mantém a tarefa sem barreira de combate a incêndio até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) posicionar extintor de classe e capacidade compatíveis junto ao ponto de trabalho, com carga, validade e lacre verificados e acesso desobstruído; (ii) designar e posicionar observador de fogo (vigia) treinado quando a tarefa ou o local o exigir, mantendo-o durante toda a execução; (iii) evidenciar a correção com registro fotográfico do extintor posicionado e da inspeção de carga ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica na ausência de válvula corta-chama/dispositivo anti-retrocesso em maçarico e reguladores de conjunto oxicombustível; rebaixar a Maior somente quando os dispositivos existirem e estiverem instalados, restando pendência de verificação funcional documental.',
  texto_fundamentacao_normativa = 'As válvulas corta-chama e os dispositivos anti-retrocesso instalados no maçarico e nos reguladores dos cilindros impedem o retrocesso de chama e o refluxo de gás no conjunto oxicombustível, evitando a propagação da chama para as mangueiras e cilindros. A exigência decorre das boas práticas de segurança em operações com oxigênio e gases combustíveis e das especificações do fabricante do equipamento, integrando o plano de inspeção da obra. O critério "dispositivos anti-retrocesso em maçarico e reguladores" constitui requisito verificável de aceitação do conjunto antes da liberação do trabalho a quente.',
  texto_risco_consequencia = 'A operação de conjunto oxicombustível sem válvulas corta-chama expõe o sistema a retrocesso de chama e refluxo de gases, com risco de explosão de mangueiras e de cilindros, projeção de estilhaços, incêndio e lesões graves ao operador e a terceiros próximos. A permanência da condição mantém o conjunto operando sem barreira contra retrocesso de chama até a instalação dos dispositivos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de operação o conjunto oxicombustível até a instalação de válvulas corta-chama/anti-retrocesso no maçarico e em ambos os reguladores (oxigênio e combustível); (ii) verificar a funcionalidade dos dispositivos conforme instrução do fabricante e registrar a conformidade; (iii) evidenciar a correção com registro fotográfico dos dispositivos instalados no maçarico e nos reguladores ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver vazamento confirmado de gás combustível ou oxigênio, mangueira ressecada/danificada ou conexão sem abraçadeira adequada em uso; manter Maior quando o desvio for de identificação/fixação sem vazamento constatado.',
  texto_fundamentacao_normativa = 'As mangueiras e conexões íntegras, sem vazamentos e com abraçadeiras adequadas, garantem a estanqueidade do conjunto oxicombustível e evitam o acúmulo de atmosfera inflamável ou enriquecida de oxigênio no posto de trabalho. O critério "sem vazamentos (teste), abraçadeiras adequadas" decorre das boas práticas de segurança em gases sob pressão e das especificações do fabricante das mangueiras e engates, integrando o plano de inspeção da obra e constituindo requisito verificável de aceitação do conjunto antes da liberação do trabalho a quente.',
  texto_risco_consequencia = 'Mangueiras ressecadas, conexões frouxas ou abraçadeiras inadequadas provocam vazamento de gás combustível ou de oxigênio, formando atmosfera inflamável ou enriquecida próximo à fonte de ignição, com risco de deflagração, incêndio e queimaduras. A permanência da condição mantém o vazamento e o acúmulo de gás ativos no posto de trabalho até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir mangueiras ressecadas, trincadas ou danificadas e reapertar/trocar conexões e abraçadeiras por modelos adequados ao serviço; (ii) executar teste de estanqueidade (solução detergente/água e sabão) em toda a linha, do regulador ao maçarico, confirmando a ausência de vazamento; (iii) evidenciar a correção com registro fotográfico das mangueiras e conexões íntegras e do teste ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o soldador executar a tarefa sem máscara de solda ou sem proteção que exponha diretamente pele/olhos a arco e respingos; manter Maior quando faltar item complementar (mangotes/perneiras) sem exposição imediata do rosto e dos olhos.',
  texto_fundamentacao_normativa = 'O EPI específico de soldador — máscara de solda com filtro adequado, avental, mangotes e perneiras — protege olhos, face, tronco e membros contra radiação do arco, respingos incandescentes e escória. Aplica-se a NR-06 (equipamento de proteção individual), que estabelece o fornecimento e o uso de EPI adequado ao risco, complementada pela NR-18 no contexto da construção e pela avaliação de riscos da tarefa. O critério "máscara de solda, avental, mangotes, perneiras" integra o plano de inspeção da obra e constitui requisito verificável de aceitação do posto de soldagem.',
  texto_risco_consequencia = 'A ausência do EPI específico de soldador expõe o trabalhador a queimaduras por respingos e escória, a ceratoconjuntivite e lesões oculares pela radiação do arco e a queimaduras de pele por radiação ultravioleta, com risco de afastamento e agravamento em exposições repetidas. A permanência da condição mantém o soldador exposto ao arco e aos respingos até a adequação do EPI. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) fornecer e exigir o uso completo do EPI de soldador — máscara com filtro adequado ao processo, avental, mangotes e perneiras em material resistente ao calor; (ii) verificar o estado de conservação e a certificação (CA) dos equipamentos, substituindo os danificados; (iii) evidenciar a correção com registro fotográfico do soldador com o EPI completo em uso ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a soldagem/corte ocorrer em ambiente confinado ou pouco ventilado sem exaustão, ou com materiais que gerem fumos tóxicos (galvanizados, revestidos); manter Maior em ambiente aberto com ventilação natural insuficiente porém sem confinamento.',
  texto_fundamentacao_normativa = 'A ventilação natural ou a exaustão forçada de fumos remove os fumos metálicos e gases gerados na solda e no corte do entorno respiratório do trabalhador, controlando a concentração de contaminantes no ar. A adequação da ventilação ao local (aberto, semiconfinado ou confinado) é boa prática consolidada de higiene ocupacional e integra o plano de inspeção da obra; a definição do meio de controle apoia-se na avaliação de riscos ambientais da tarefa. O critério "natural ou forçada conforme local" constitui requisito verificável de aceitação das condições de execução do trabalho a quente.',
  texto_risco_consequencia = 'A falta de ventilação ou exaustão adequada permite o acúmulo de fumos metálicos e gases no ar respirado pelo soldador, com risco de intoxicação, febre dos fumos metálicos e efeitos respiratórios, agravado em ambientes confinados por deficiência de oxigênio. A permanência da condição mantém a exposição a fumos no posto de trabalho até a implantação do controle de ventilação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) prover ventilação natural cruzada ou instalar exaustão forçada localizada (captação junto à fonte de fumos), dimensionada ao local e ao processo; (ii) em ambiente confinado ou de ventilação insuficiente, associar proteção respiratória adequada e monitoramento da atmosfera antes e durante a tarefa; (iii) evidenciar a correção com registro fotográfico do sistema de ventilação/exaustão em operação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que a área não for monitorada após o término do serviço pelo tempo mínimo (30 min); rebaixar a Maior apenas quando houver vigilância parcial registrada, restando ajuste de tempo ou de abrangência da ronda de inspeção final.',
  texto_fundamentacao_normativa = 'A vigilância pós-serviço consiste no monitoramento da área após o término do trabalho a quente por tempo mínimo (mín. 30 min) para detectar e extinguir focos latentes de combustão iniciados por fagulhas e escória que permanecem quentes e podem deflagrar incêndio após a conclusão da tarefa. O critério "área monitorada após término (mín. 30 min)" é boa prática consolidada de gestão de trabalho a quente e integra o plano de emergência e o plano de inspeção da obra, constituindo requisito verificável de encerramento seguro da tarefa e de fechamento da PT.',
  texto_risco_consequencia = 'A ausência de vigilância pós-serviço deixa focos latentes de combustão sem monitoramento, permitindo a deflagração de incêndio após a saída da equipe, quando não há ninguém para combatê-lo em fase inicial, com risco de propagação, perdas materiais e danos a instalações. A permanência da condição mantém o período crítico pós-serviço sem monitoramento até a correção do procedimento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instituir e cumprir a ronda de vigilância pós-serviço, mantendo a área monitorada por no mínimo 30 minutos após o término, com meio de combate a incêndio disponível; (ii) registrar a inspeção final e o encerramento na PT, confirmando a inexistência de focos e pontos quentes; (iii) evidenciar a correção com registro fotográfico da vigilância e do fechamento da PT ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-13' and item_numero = 8;

-- ST-14 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que houver trabalhadores no interior da vala ou escavação, dado o risco de soterramento; rebaixar a Maior apenas em escavação já concluída, estabilizada e sem acesso de pessoas.',
  texto_fundamentacao_normativa = 'A estabilidade da parede de escavação deve ser garantida por talude com inclinação compatível ou por escoramento dimensionado, definidos em função da profundidade, do tipo de solo e das cargas de borda. Aplicam-se a NR-18, que exige proteção contra desmoronamento em escavações, e a NBR 9061 (segurança de escavação a céu aberto), que orienta a estabilidade de taludes e o dimensionamento de contenções. Quando o escoramento for projetado, valem também o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "conforme profundidade e tipo de solo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de talude adequado ou de escoramento dimensionado permite o desmoronamento súbito da parede da escavação, com soterramento e risco de morte de trabalhadores, além de danos a estruturas vizinhas e paralisação da frente de serviço. A permanência da condição expõe continuamente as equipes ao colapso do maciço até a efetiva estabilização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interditar imediatamente o acesso de pessoas ao interior da escavação até a estabilização; (ii) implantar talude com inclinação compatível ao solo ou instalar escoramento dimensionado por profissional habilitado, conforme sondagem e projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo/ART do responsável técnico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver rede de gás, rede elétrica energizada ou adutora sob pressão no traçado da escavação, pelo potencial de explosão, choque ou inundação.',
  texto_fundamentacao_normativa = 'O reconhecimento prévio de sondagens e interferências enterradas (redes elétricas, água, gás e drenagem) é condição para o planejamento seguro da escavação e deve preceder qualquer corte no solo. Aplica-se a NR-18, que exige a identificação prévia de instalações e interferências antes da escavação; para as redes elétricas subterrâneas aplica-se ainda a NR-10 (segurança em instalações e serviços em eletricidade). O mapeamento deve confrontar cadastros das concessionárias, sondagens e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "redes elétricas, água, gás e drenagem mapeadas" constitui requisito verificável de liberação da frente.',
  texto_risco_consequencia = 'Escavar sem mapear interferências pode romper redes de gás, energia, água ou drenagem, provocando explosão, incêndio, choque elétrico, inundação da vala e interrupção de serviços a terceiros, com risco à vida das equipes e responsabilização perante concessionárias. Enquanto o cadastro de interferências não for confirmado, cada avanço da escavação repete o risco de atingir rede não identificada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a escavação no trecho e obter os cadastros de redes junto às concessionárias, complementados por sondagem/prospecção manual (poços de inspeção) quando necessário; (ii) mapear e sinalizar em campo o traçado das interferências, prevendo desvio, desligamento ou proteção mecânica antes de retomar o corte; (iii) evidenciar a verificação com registro fotográfico ({{evidencia_foto_correcao}}) e croqui de interferências atualizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a vala ultrapassar 1,25 m de profundidade e não houver qualquer meio de saída rápida junto às frentes com pessoas.',
  texto_fundamentacao_normativa = 'Escavações com profundidade superior a 1,25 m exigem meios de acesso e saída que permitam evacuação rápida, com escadas ou rampas distribuídas de modo que o deslocamento máximo até uma saída seja limitado. Aplica-se a NR-18, que estabelece a obrigatoriedade de escadas de acesso em escavações e a distância máxima entre pontos de saída. O critério "saída rápida garantida em valas > 1,25 m", com escadas a cada 15 m, integra o plano de inspeção e constitui requisito verificável de aceitação da frente.',
  texto_risco_consequencia = 'A falta de escadas de acesso a cada 15 m impede a evacuação rápida em caso de desmoronamento, alagamento súbito ou emergência, prendendo o trabalhador no fundo da vala e agravando lesões e o risco de morte, além de dificultar o resgate. Enquanto os pontos de saída não forem regularizados, toda equipe que desce à vala fica sem rota de fuga adequada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar escadas ou rampas de acesso fixadas e apoiadas, espaçadas no máximo a cada 15 m ao longo da vala, prolongadas acima da borda para apoio; (ii) verificar o dimensionamento e a ancoragem das escadas e sinalizar os pontos de saída; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) mostrando o espaçamento atendido, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o solo escavado ou materiais estiverem depositados sobre a própria borda, sobrecarregando o talude com pessoas trabalhando na vala.',
  texto_fundamentacao_normativa = 'O material proveniente da escavação e demais cargas devem ser mantidos afastados no mínimo 1 m da borda, evitando sobrecarga no maciço e queda de material sobre trabalhadores. Aplica-se a NR-18, que determina o afastamento do material escavado da beira da vala, complementada pela NBR 9061 no que se refere à estabilidade do talude sob cargas de borda. O critério "solo escavado e materiais afastados" constitui requisito verificável de aceitação da frente de escavação.',
  texto_risco_consequencia = 'Material depositado junto à borda impõe sobrecarga ao talude e favorece o desmoronamento, além de permitir a queda de solo, pedras e ferramentas sobre quem trabalha no interior da vala, com risco de soterramento e lesões por impacto. A permanência da condição mantém o maciço sobrecarregado e o fundo da vala exposto à queda de material até o efetivo afastamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reposicionar o solo escavado e os materiais para distância mínima de 1 m da borda, preferencialmente no lado oposto ao acesso de pessoas; (ii) manter a faixa de borda livre e, quando aplicável, instalar rodapé/anteparo para conter rolamento de material; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) mostrando o afastamento atendido, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a escavação estiver em área de circulação de pessoas ou veículos e permanecer sem barreira física em parte do perímetro.',
  texto_fundamentacao_normativa = 'O perímetro da escavação deve ser isolado por barreira física resistente (guarda-corpo ou tela) e sinalizado, impedindo a aproximação e a queda de pessoas na vala. Aplica-se a NR-18, que exige o isolamento e a sinalização das áreas de escavação e a proteção de aberturas no piso contra quedas. O critério "guarda-corpo/tela em todo o perímetro" integra o plano de inspeção e constitui requisito verificável de aceitação da proteção coletiva.',
  texto_risco_consequencia = 'A ausência de barreira física e sinalização em todo o perímetro permite a queda de trabalhadores e de terceiros no interior da escavação, além da aproximação indevida da borda, com risco de lesões graves, fraturas e soterramento. Enquanto houver trecho de perímetro desprotegido, mantém-se aberta a via de acesso involuntário à vala. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar guarda-corpo ou tela contínua em todo o perímetro da escavação, com resistência e altura adequadas, sem trechos descobertos; (ii) complementar com sinalização de advertência diurna e noturna e isolamento das rotas de circulação próximas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do perímetro integralmente protegido, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o acúmulo de água comprometer a estabilidade do talude/escoramento ou houver pessoas trabalhando na vala inundada.',
  texto_fundamentacao_normativa = 'A presença de água na escavação deve ser controlada por drenagem e bombeamento, com verificação da estabilidade do maciço, pois a saturação do solo reduz sua resistência e favorece o colapso das paredes. Aplicam-se a NR-18, quanto às medidas de estabilização e drenagem de escavações, e a NBR 9061, no tratamento do efeito da água sobre a estabilidade de taludes; quando houver contenção projetada, vale o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "bombeamento e estabilidade verificada" constitui requisito verificável de liberação da frente.',
  texto_risco_consequencia = 'Água acumulada satura e amolece o solo, reduzindo a coesão e podendo provocar desmoronamento das paredes, colapso do fundo e afogamento em valas profundas, além de instabilizar equipamentos e escoramentos. Enquanto o bombeamento e a reavaliação da estabilidade não forem executados, o maciço permanece enfraquecido e sujeito a ruptura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar e manter bombeamento/drenagem para rebaixar o nível de água na escavação; (ii) reavaliar a estabilidade do talude ou escoramento após o esgotamento, reforçando a contenção quando indicado por profissional habilitado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da vala drenada e do sistema de bombeamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a escavação for retomada após chuva, vibração ou percolação sem a reavaliação do talude, com trabalhadores retornando ao interior da vala.',
  texto_fundamentacao_normativa = 'A escavação deve ser inspecionada diariamente e sempre reavaliada após chuvas, vibrações ou eventos que alterem a estabilidade do talude, por profissional legalmente habilitado ou responsável designado. Aplica-se a NR-18, que exige inspeção prévia e periódica das escavações por profissional habilitado antes do início e durante os trabalhos. O critério "após chuva ou vibração, reavaliação do talude" integra o plano de inspeção e constitui requisito verificável de liberação diária da frente.',
  texto_risco_consequencia = 'A falta de inspeção diária e de reavaliação após chuva ou vibração faz com que trincas, descalçamentos e perda de coesão do talude passem despercebidos, culminando em desmoronamento sem aviso sobre as equipes na vala. Enquanto a rotina de inspeção não for restabelecida, a evolução do dano no maciço deixa de ser detectada a tempo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instituir e registrar inspeção diária da escavação por profissional habilitado, com reavaliação obrigatória após chuva, vibração ou percolação, antes de liberar o acesso; (ii) formalizar a liberação da frente em check-list/ordem de serviço, condicionando o retorno das equipes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os registros de inspeção preenchidos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando máquinas ou veículos pesados operarem ou trafegarem junto à borda da escavação com trabalhadores no interior da vala.',
  texto_fundamentacao_normativa = 'Equipamentos e máquinas pesadas devem operar a distância segura da borda da escavação, pois as cargas dinâmicas e o peso próximo à crista aumentam a solicitação sobre o maciço e o risco de ruptura. Aplica-se a NR-18, quanto ao afastamento de cargas e equipamentos da borda de escavações; a distância segura deve considerar a profundidade, o tipo de solo e as cargas do equipamento, conforme avaliação de profissional habilitado. O critério "distância segura de equipamentos pesados" constitui requisito verificável de aceitação da frente.',
  texto_risco_consequencia = 'Máquinas operando junto à borda impõem sobrecarga e vibração ao talude, podendo desencadear o desmoronamento da parede sobre os trabalhadores, além do risco de tombamento do próprio equipamento para dentro da vala. Enquanto o afastamento seguro não for definido e respeitado, cada manobra próxima à crista renova o risco de colapso. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir e demarcar em campo a distância mínima segura de operação e tráfego dos equipamentos em relação à borda, conforme avaliação técnica da profundidade e do solo; (ii) instalar batentes/limitadores físicos e sinalização, orientando os operadores; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) mostrando o afastamento e a demarcação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ST-14' and item_numero = 8;

